import React from 'react';
import { ArrowRight } from 'lucide-react';
import { BlogPost } from '../types';

interface BlogCardProps {
  post: BlogPost;
  onReadMore: (post: BlogPost) => void;
}

const formatDate = (dateString: string) => {
  if (!dateString) return '';
  const date = new Date(dateString);
  if (isNaN(date.getTime())) return dateString;
  return new Intl.DateTimeFormat('en-US', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: true
  }).format(date);
};

const BlogCard: React.FC<BlogCardProps> = ({ post, onReadMore }) => (
  <div className="bg-white rounded-xl shadow-md hover:shadow-xl transition-shadow duration-300 overflow-hidden flex flex-col h-full border border-gray-100">
    <div className="h-48 overflow-hidden">
      <img src={post.imageUrl} alt={post.title} className="w-full h-full object-cover transition-transform duration-500 hover:scale-110" />
    </div>
    <div className="p-6 flex-grow flex flex-col">
      <span className="text-xs font-bold text-leaf uppercase tracking-wider mb-2">{formatDate(post.date)}</span>
      <h3 className="text-xl font-bold text-gray-800 mb-3 line-clamp-2">{post.title}</h3>
      <p className="text-gray-600 text-sm mb-4 line-clamp-3 flex-grow">{post.excerpt}</p>
      <button 
        onClick={() => onReadMore(post)}
        className="text-soil hover:text-leaf font-semibold text-sm flex items-center mt-auto"
      >
        Read More <ArrowRight size={16} className="ml-1" />
      </button>
    </div>
  </div>
);

export default BlogCard;

import React, { useEffect, useState, useRef } from 'react';
import { X, DollarSign, CreditCard, Download } from 'lucide-react';
import toast from 'react-hot-toast';
import Modal from './Modal';
import BlogCard from './BlogCard';
import { useModal } from '../context/ModalContext';
import { MOCK_BLOG_POSTS, MOCK_GALLERY, APP_LOGO_URL } from '../constants';
import { BlogPost, GalleryItem, User } from '../types';
import { getBlogPosts, submitDonation } from '../services/googleSheetService';

const formatDate = (dateString: string) => {
  if (!dateString) return '';
  const date = new Date(dateString);
  if (isNaN(date.getTime())) return dateString;
  return new Intl.DateTimeFormat('en-US', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: true
  }).format(date);
};

const GlobalModals: React.FC = () => {
  const { activeModal, closeModal, openModal, modalData } = useModal();
  const [posts, setPosts] = useState<BlogPost[]>(MOCK_BLOG_POSTS);

  // ID Card Ref
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Donation Form State
  const [donationForm, setDonationForm] = useState({ name: '', email: '', amount: '', method: 'Bkash', account: '', trxId: '' });
  const [isDonating, setIsDonating] = useState(false);

  // Fetch real posts when a relevant modal opens
  useEffect(() => {
    if (activeModal === 'activities' || activeModal === 'success' || activeModal === 'gallery') {
      getBlogPosts().then(fetchedPosts => {
        if (fetchedPosts.length > 0) setPosts(fetchedPosts);
      });
    }
  }, [activeModal]);

  // ID Card Generation Logic
  useEffect(() => {
    if (activeModal === 'idCard' && modalData && canvasRef.current) {
       drawIdCard(modalData as User);
    }
  }, [activeModal, modalData]);

  const handleOpenPost = (post: BlogPost) => {
    openModal('post', post);
  };

  const handleDonationSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsDonating(true);
    const success = await submitDonation(donationForm.name, donationForm.email, donationForm.amount, donationForm.method, donationForm.account, donationForm.trxId);
    if (success) {
      toast.success("Donation details submitted! We will verify shortly.");
      setDonationForm({ name: '', email: '', amount: '', method: 'Bkash', account: '', trxId: '' });
      closeModal();
    } else {
      toast.error("Failed to submit donation.");
    }
    setIsDonating(false);
  };

  const drawIdCard = (user: User) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Load assets
    const logoImg = new Image();
    logoImg.src = APP_LOGO_URL;
    logoImg.crossOrigin = "Anonymous";

    const profileImg = new Image();
    // Use a placeholder if no photo, or proxy if cross-origin issues
    profileImg.src = user.data?.photoUrl || `https://ui-avatars.com/api/?background=random&color=fff&name=${encodeURIComponent(user.name)}`;
    profileImg.crossOrigin = "Anonymous";

    const draw = () => {
      // 1. Clear Canvas & Background
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(0, 0, 600, 380);

      // 2. Header Background (Soil Color)
      ctx.fillStyle = "#5D4037"; // Soil Color
      ctx.fillRect(0, 0, 600, 100);

      // 3. Header Text
      ctx.textAlign = "center";
      ctx.fillStyle = "#ffffff";

      // Association Name
      ctx.font = "bold 24px Arial";
      ctx.fillText("Soil Science Alumni Association", 270, 45); // Shifted left to make room for logo on right

      // College Name (Full)
      ctx.font = "15px Arial";
      ctx.fillText("Government Shaheed Suhrawardy College", 270, 70);

      // 4. Logo (Top Right with White Circle Background for visibility)
      // Canvas Width 600. Center of circle at x = 530, y = 50. Radius 40.
      ctx.save();
      ctx.beginPath();
      ctx.arc(530, 50, 40, 0, Math.PI * 2, true); // White circle behind logo
      ctx.fillStyle = "#ffffff";
      ctx.fill();
      ctx.closePath();

      try {
        // Draw logo centered in the white circle
        // 530 - 35 = 495
        ctx.drawImage(logoImg, 495, 15, 70, 70); 
      } catch(e) {
        // Fallback if logo fails
        ctx.fillStyle = "#ccc";
        ctx.fill();
        ctx.fillStyle = "#5D4037";
        ctx.font = "bold 20px Arial";
        ctx.fillText("SSAA", 530, 55);
      }
      ctx.restore();

      // 5. Profile Photo (Circular with Green Border)
      // Position: Vertical Center Left
      const photoX = 100;
      const photoY = 220;
      const photoRadius = 75;

      ctx.save();
      ctx.beginPath();
      ctx.arc(photoX, photoY, photoRadius, 0, Math.PI * 2, true);
      ctx.closePath();
      ctx.clip();

      // Background for transparent images
      ctx.fillStyle = "#f3f4f6";
      ctx.fillRect(photoX - photoRadius, photoY - photoRadius, photoRadius * 2, photoRadius * 2);

      try {
        // Draw image cover style
        ctx.drawImage(profileImg, photoX - photoRadius, photoY - photoRadius, photoRadius * 2, photoRadius * 2);
      } catch (e) {
        ctx.fillStyle = "#ccc";
        ctx.fillRect(photoX - photoRadius, photoY - photoRadius, photoRadius * 2, photoRadius * 2);
        ctx.fillStyle = "#666";
        ctx.font = "bold 40px Arial";
        ctx.fillText(user.name.charAt(0), photoX, photoY + 15);
      }
      ctx.restore();

      // Border for photo
      ctx.beginPath();
      ctx.arc(photoX, photoY, photoRadius, 0, Math.PI * 2, true);
      ctx.strokeStyle = "#43A047"; // Leaf Green
      ctx.lineWidth = 6;
      ctx.stroke();

      // 6. User Details (Right Side)
      ctx.textAlign = "left";
      const textStartX = 210;
      let textY = 160;

      // Name (Large)
      ctx.fillStyle = "#1f2937"; // Dark Gray
      ctx.font = "bold 28px Arial";
      ctx.fillText(user.name, textStartX, textY);

      // Divider Line
      textY += 15;
      ctx.beginPath();
      ctx.moveTo(textStartX, textY);
      ctx.lineTo(550, textY);
      ctx.strokeStyle = "#e5e7eb";
      ctx.lineWidth = 2;
      ctx.stroke();

      // Info Grid
      textY += 35;
      const labelOffset = 0;
      const valueOffset = 130; // Increased to fit "Membership ID"
      const rowGap = 35;

      // Helper function for rows
      const drawRow = (label: string, value: string, color: string = "#374151") => {
        ctx.font = "bold 14px Arial";
        ctx.fillStyle = "#8D6E63"; // Light Soil (Label color)
        ctx.fillText(label, textStartX + labelOffset, textY);

        ctx.font = "bold 16px Arial";
        ctx.fillStyle = color; // Value color
        ctx.fillText(value, textStartX + valueOffset, textY);

        textY += rowGap;
      };

      // UPDATED SEQUENCE: Membership ID -> Session -> Batch -> Blood
      drawRow("Membership ID:", user.data?.password || "N/A");
      drawRow("Session:", user.data?.session || "N/A");
      drawRow("Batch:", user.data?.batch || "N/A");
      drawRow("Blood:", user.data?.bloodGroup || "N/A", "#dc2626"); // Red for blood

      // 7. Footer Strip
      ctx.fillStyle = "#43A047"; // Leaf Green
      ctx.fillRect(0, 360, 600, 20);

      ctx.textAlign = "center";
      ctx.font = "12px math ";
      ctx.fillStyle = "#fff";
      ctx.fillText("gsscsoilalumni@gmail.com  |  Estd. 2020", 300, 374);
    };

    // Wait for images to load
    let loaded = 0;
    const checkLoad = () => {
      loaded++;
      if (loaded >= 2) draw();
    };
    logoImg.onload = checkLoad;
    logoImg.onerror = checkLoad; // Draw anyway even if logo fails
    profileImg.onload = checkLoad;
    profileImg.onerror = checkLoad;

    // Trigger draw immediately in case cached
    if (logoImg.complete && profileImg.complete) draw();
    // Also set timeout fallback just in case
    setTimeout(draw, 500);
  };

  const downloadIdCard = () => {
    if (!canvasRef.current) return;
    const link = document.createElement('a');
    link.download = `SSAA-ID-${modalData?.name || 'Member'}.png`;
    link.href = canvasRef.current.toDataURL();
    link.click();
  };

  // Convert posts to gallery items
  const postImages: GalleryItem[] = posts
    .filter(p => p.imageUrl)
    .map(p => ({
      id: p.id,
      title: p.title,
      description: p.excerpt,
      category: p.category,
      imageUrl: p.imageUrl
    }));

  const fullGallery = [...postImages, ...MOCK_GALLERY];

  return (
    <>
      {/* 1. About Us Modal */}
      <Modal 
        isOpen={activeModal === 'about'} 
        onClose={closeModal} 
        title="About SSAA - GSSC"
      >
        <div className="prose prose-lg mx-auto text-gray-700 p-4">
          <h3 className="text-2xl font-bold text-soil mb-4">Our History</h3>
          <p className="mb-8">
            Established in 2020, the Soil Science Alumni Association (SSAA) of Govt. Shaheed Suhrawardy College began as a small initiative to keep graduates connected. Over the years, it has blossomed into a vibrant community of professionals, researchers, and academicians dedicated to the advancement of Soil Science.
          </p>
          <h3 className="text-2xl font-bold text-soil mb-4">Vision</h3>
          <p className="mb-8">
            To become a premier platform for professional development and to create a sustainable environment through the application of soil science knowledge.
          </p>
          <h3 className="text-2xl font-bold text-soil mb-4">The Department</h3>
          <p>
             The Department of Soil Science at Govt. Shaheed Suhrawardy College has a rich tradition of excellence. Our alumni are spread across the globe, contributing significantly to agriculture, environmental science, and policy-making. This association serves as a bridge between the glorious past and the promising future of the department.
          </p>
        </div>
      </Modal>

      {/* 2. All Activities Modal */}
      <Modal 
        isOpen={activeModal === 'activities'} 
        onClose={closeModal} 
        title="All Recent Activities"
      >
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 pb-4">
          {posts.filter(p => p.category === 'Activity').map(post => (
             <BlogCard key={post.id} post={post} onReadMore={handleOpenPost} />
          ))}
        </div>
      </Modal>

      {/* 3. Success Stories Modal */}
      <Modal 
        isOpen={activeModal === 'success'} 
        onClose={closeModal} 
        title="Alumni Success Stories"
      >
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 pb-4">
          {posts.filter(p => p.category === 'Success').map(post => (
             <BlogCard key={post.id} post={post} onReadMore={handleOpenPost} />
          ))}
        </div>
      </Modal>

      {/* 4. Photo Gallery Modal (UPDATED) */}
      <Modal 
        isOpen={activeModal === 'gallery'} 
        onClose={closeModal} 
        title="Photo Gallery"
      >
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 pb-4">
           {fullGallery.map((item) => (
            <div 
              key={item.id} 
              className="relative aspect-square group cursor-pointer overflow-hidden rounded-lg shadow-sm bg-gray-100"
              onClick={() => openModal('image', item)}
            >
              <img 
                src={item.imageUrl} 
                alt={item.title} 
                className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" 
              />
              <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex flex-col items-center justify-center text-white p-4 text-center">
                <h4 className="font-bold text-lg">{item.title}</h4>
              </div>
            </div>
          ))}
        </div>
      </Modal>

      {/* 5. Single Post Reader */}
      <Modal
        isOpen={activeModal === 'post' && !!modalData}
        onClose={closeModal}
        title={modalData?.title || "Article"}
        maxWidth="max-w-4xl"
      >
        {modalData && (
          <div className="bg-white">
            <div className="h-64 md:h-80 w-full overflow-hidden rounded-xl mb-6">
              <img src={modalData.imageUrl} alt={modalData.title} className="w-full h-full object-cover" />
            </div>
            <div className="px-2">
              <div className="flex items-center space-x-4 mb-4 text-sm text-gray-500">
                <span className="font-bold text-leaf bg-leaf/10 px-3 py-1 rounded-full">{modalData.category}</span>
                <span>{formatDate(modalData.date)}</span>
              </div>
              <h2 className="text-3xl font-bold text-gray-900 mb-6">{modalData.title}</h2>
              <div className="prose prose-lg text-gray-700 max-w-none">
                 {modalData.content ? (
                   <div dangerouslySetInnerHTML={{ __html: modalData.content }} />
                 ) : (
                   <>
                     <p className="lead text-xl text-gray-600 mb-4">{modalData.excerpt}</p>
                     <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat.</p>
                     <p>Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.</p>
                     <p>Detailed report of the event goes here. It describes the attendees, the guest speakers, and the outcomes of the session. The alumni association is proud to organize such events regularly.</p>
                   </>
                 )}
              </div>
            </div>
          </div>
        )}
      </Modal>

      {/* 6. Image Lightbox Overlay */}
      {activeModal === 'image' && modalData && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/95 p-4" onClick={closeModal}>
          <button className="absolute top-6 right-6 text-white hover:text-gray-300 focus:outline-none bg-white/10 p-2 rounded-full backdrop-blur-sm">
            <X size={32} />
          </button>

          <div 
            className="max-w-5xl w-full bg-white rounded-lg overflow-hidden flex flex-col md:flex-row shadow-2xl" 
            onClick={(e) => e.stopPropagation()}
          >
            <div className="md:w-3/4 h-[50vh] md:h-[80vh] bg-black flex items-center justify-center">
              <img src={modalData.imageUrl} alt={modalData.title} className="max-w-full max-h-full object-contain" />
            </div>
            <div className="md:w-1/4 p-8 flex flex-col justify-center bg-white border-l border-gray-200">
              <span className="text-xs font-bold text-leaf uppercase tracking-wider mb-2">{modalData.category}</span>
              <h2 className="text-2xl font-bold text-gray-900 mb-4">{modalData.title}</h2>
              <p className="text-gray-600 leading-relaxed">{modalData.description}</p>
            </div>
          </div>
        </div>
      )}

      {/* 7. Donation Modal */}
      <Modal 
        isOpen={activeModal === 'donation'} 
        onClose={closeModal} 
        title="Donate Now"
      >
        <div className="p-4">
           <div className="bg-soil/5 p-6 rounded-xl border border-soil/10 mb-6">
              <h3 className="text-lg font-bold text-soil mb-4 flex items-center"><CreditCard className="mr-2" size={20} /> Payment Methods</h3>
              <div className="space-y-3 text-sm">
                <div className="flex justify-between items-center p-3 bg-white rounded-lg shadow-sm">
                  <span className="font-bold text-pink-600">Bkash (Personal)</span>
                  <span className="font-mono text-gray-700 font-bold select-all">01714 605 024</span>
                </div>
                <div className="flex justify-between items-center p-3 bg-white rounded-lg shadow-sm">
                  <span className="font-bold text-orange-600">Nagad (Personal)</span>
                  <span className="font-mono text-gray-700 font-bold select-all">01714 605 024</span>
                </div>
              </div>
              <p className="mt-3 text-xs text-gray-500 italic">
                * Please send money first using "Send Money". Then fill out the form below.
              </p>
           </div>

           <form onSubmit={handleDonationSubmit} className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <input required name="name" value={donationForm.name} onChange={e => setDonationForm({...donationForm, name: e.target.value})} className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-leaf outline-none" placeholder="Your Name" />
                <input required name="email" value={donationForm.email} onChange={e => setDonationForm({...donationForm, email: e.target.value})} className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-leaf outline-none" placeholder="Email" />
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <input required name="amount" value={donationForm.amount} onChange={e => setDonationForm({...donationForm, amount: e.target.value})} className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-leaf outline-none" placeholder="Amount (BDT)" />
                <select value={donationForm.method} onChange={e => setDonationForm({...donationForm, method: e.target.value})} className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-leaf outline-none bg-white">
                  <option value="Bkash">Bkash</option>
                  <option value="Nagad">Nagad</option>
                  <option value="Rocket">Rocket</option>
                  <option value="Bank">Bank Transfer</option>
                </select>
              </div>
              <input required name="account" value={donationForm.account} onChange={e => setDonationForm({...donationForm, account: e.target.value})} className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-leaf outline-none" placeholder="Sent From (Phone/Acc No)" />
              <input required name="trxId" value={donationForm.trxId} onChange={e => setDonationForm({...donationForm, trxId: e.target.value})} className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-leaf outline-none" placeholder="Transaction ID (TrxID)" />

              <button type="submit" disabled={isDonating} className="w-full bg-leaf hover:bg-leaf-dark text-white font-bold py-3 rounded-lg transition-colors disabled:opacity-70 flex justify-center items-center">
                {isDonating ? "Submitting..." : <><DollarSign size={18} className="mr-2"/> Submit Donation Details</>}
              </button>
           </form>
        </div>
      </Modal>

      {/* 8. DIGITAL ID CARD MODAL (NEW) */}
      <Modal
        isOpen={activeModal === 'idCard'}
        onClose={closeModal}
        title="Your Digital Alumni Card"
      >
        <div className="flex flex-col items-center p-4">
           {/* Canvas Container */}
           <div className="bg-gray-200 p-1 rounded-lg shadow-inner mb-6 overflow-x-auto max-w-full flex justify-center">
              <canvas 
                ref={canvasRef} 
                width={600} 
                height={380} 
                className="bg-white rounded shadow-lg max-w-full h-auto object-contain"
              />
           </div>

           <div className="text-center space-y-4">
             <p className="text-sm text-gray-500 max-w-md">
               This is your official digital membership card. You can present this on your mobile device during events or print it for your records.
             </p>
             <button 
               onClick={downloadIdCard}
               className="bg-soil hover:bg-soil-dark text-white font-bold py-3 px-8 rounded-full shadow-lg transform transition-all hover:scale-105 flex items-center mx-auto"
             >
               <Download size={20} className="mr-2" /> Download ID Card
             </button>
           </div>
        </div>
      </Modal>
    </>
  );
};

export default GlobalModals;

import React, { useState } from 'react';
import { MOCK_BLOG_POSTS } from '../constants';
import SectionTitle from '../components/SectionTitle';

const formatDate = (dateString: string) => {
  if (!dateString) return '';
  const date = new Date(dateString);
  if (isNaN(date.getTime())) return dateString;
  return new Intl.DateTimeFormat('en-US', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: true
  }).format(date);
};

const Blog: React.FC = () => {
  const [filter, setFilter] = useState<'All' | 'Activity' | 'Success'>('All');

  const filteredPosts = filter === 'All' 
    ? MOCK_BLOG_POSTS 
    : MOCK_BLOG_POSTS.filter(post => post.category === filter);

  return (
    <div className="bg-gray-50 min-h-screen pb-20">
      <div className="bg-soil text-white py-16 mb-12">
        <div className="max-w-7xl mx-auto px-4 text-center">
          <h1 className="text-4xl font-bold">News & Updates</h1>
          <p className="mt-4 text-soil-light">Stay updated with our latest activities and success stories.</p>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Filters */}
        <div className="flex justify-center mb-12 space-x-4">
          {['All', 'Activity', 'Success'].map((cat) => (
            <button
              key={cat}
              onClick={() => setFilter(cat as any)}
              className={`px-6 py-2 rounded-full font-medium transition-all duration-300 ${
                filter === cat 
                  ? 'bg-soil text-white shadow-lg transform scale-105' 
                  : 'bg-white text-gray-600 hover:bg-gray-200'
              }`}
            >
              {cat === 'All' ? 'All Posts' : cat === 'Activity' ? 'Recent Activities' : 'Alumni Success'}
            </button>
          ))}
        </div>

        {/* Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {filteredPosts.map((post) => (
            <div key={post.id} className="bg-white rounded-xl shadow-sm overflow-hidden hover:shadow-md transition-all duration-300 border border-gray-100">
              <div className="relative h-64">
                <img src={post.imageUrl} alt={post.title} className="w-full h-full object-cover" />
                <div className="absolute top-4 right-4 bg-white/90 backdrop-blur px-3 py-1 rounded-full text-xs font-bold text-soil shadow-sm">
                  {post.category}
                </div>
              </div>
              <div className="p-6">
                <div className="text-sm text-gray-500 mb-2">{formatDate(post.date)}</div>
                <h3 className="text-xl font-bold text-gray-900 mb-3">{post.title}</h3>
                <p className="text-gray-600 leading-relaxed">{post.excerpt}</p>
                <button className="mt-6 text-leaf font-semibold hover:text-leaf-dark transition-colors">
                  Read Full Story &rarr;
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Blog;

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  LogOut, User as UserIcon, MessageSquare, Users, Briefcase, FileText, 
  Send, Plus, Check, X as XIcon, Search, Loader2, Menu, LayoutDashboard, Heart, RefreshCw, PenTool, Upload, Edit, ExternalLink, Headphones,
  MessageCircle, Mail, Phone, MapPin, Calendar, Grid, Award, DollarSign, ChevronLeft, ShieldAlert, CreditCard, Gift, Megaphone
} from 'lucide-react';
import toast from 'react-hot-toast';
import { User, ChatMessage, AlumniRegistrationData, JobPost, BlogPost, Donation } from '../types';
import { 
  getAllMembers, updateMemberStatus, sendChatMessage, getBatchMessages, 
  createBlogPost, updateBlogPost, getBlogPosts, createJobPost, getJobPosts, updateUserProfile, getDonations, updateDonationStatus,
  getAdminNotice, updateAdminNotice
} from '../services/googleSheetService';
import { APP_LOGO_URL } from '../constants';
import { useModal } from '../context/ModalContext';

// Helper interface for Admin Messenger
interface ConversationSummary {
  email: string;
  name: string;
  photoUrl: string;
  lastMessage: string;
  timestamp: string;
  unreadCount: number;
}

const formatDate = (dateString: string) => {
  if (!dateString) return '';
  const date = new Date(dateString);
  if (isNaN(date.getTime())) return dateString;
  return new Intl.DateTimeFormat('en-US', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: true
  }).format(date);
};

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const { openModal } = useModal();

  const [user, setUser] = useState<User | null>(null);
  const [allMembers, setAllMembers] = useState<AlumniRegistrationData[]>([]);
  const [activeTab, setActiveTab] = useState<'profile' | 'admin' | 'chat' | 'post' | 'career' | 'search' | 'donation'>('profile');
  const [isSidebarOpen, setSidebarOpen] = useState(window.innerWidth > 768);

  // Profile Edit State
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editProfileForm, setEditProfileForm] = useState({ designation: '', company: '', currentAddress: '', bloodGroup: '', photo: null as File | null, dob: '' });
  const [editPhotoPreview, setEditPhotoPreview] = useState<string | null>(null);
  const [isUpdatingProfile, setIsUpdatingProfile] = useState(false);

  // Chat State
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [isSendingMsg, setIsSendingMsg] = useState(false);
  const [isRefreshingChat, setIsRefreshingChat] = useState(false);

  // Member Chat State
  const [memberChatMode, setMemberChatMode] = useState<'BATCH' | 'ADMIN'>('BATCH');

  // Admin Chat State
  const [adminChatSession, setAdminChatSession] = useState<string>(''); 
  const [adminChatMode, setAdminChatMode] = useState<'BATCH' | 'DM'>('BATCH');
  const [adminSelectedMemberEmail, setAdminSelectedMemberEmail] = useState<string>('');
  const [conversations, setConversations] = useState<ConversationSummary[]>([]); // New: For Messenger Sidebar

  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatIntervalRef = useRef<number | null>(null);

  // Post State
  const [posts, setPosts] = useState<BlogPost[]>([]);
  const [isEditingPost, setIsEditingPost] = useState<string | null>(null);
  const [postForm, setPostForm] = useState({ title: '', category: 'Activity', excerpt: '', content: '', image: null as File | null });
  const [postImagePreview, setPostImagePreview] = useState<string | null>(null);
  const [isPosting, setIsPosting] = useState(false);

  // Job State
  const [jobs, setJobs] = useState<JobPost[]>([]);
  const [jobForm, setJobForm] = useState({ title: '', company: '', deadline: '', link: '' });

  // Search State
  const [searchQuery, setSearchQuery] = useState('');
  const [bloodFilter, setBloodFilter] = useState('');

  // Donation State
  const [donations, setDonations] = useState<Donation[]>([]);

  // Admin Notice State
  const [adminNotice, setAdminNotice] = useState('');
  const [isEditingNotice, setIsEditingNotice] = useState(false);
  const [newNoticeText, setNewNoticeText] = useState('');

  const topRef = useRef<HTMLDivElement>(null);

  const uniqueSessions = Array.from(new Set(allMembers.map(m => m.session).filter(Boolean))).sort();

  useEffect(() => {
    const checkAuth = async () => {
      const storedUser = localStorage.getItem('ssaa_current_user');
      if (!storedUser) { navigate('/login'); return; }
      const parsedUser: User = JSON.parse(storedUser);
      setUser(parsedUser);
      getAllMembers().then(setAllMembers);
      loadPosts();
      loadNotice();
    };
    checkAuth();
    return () => stopChatPolling();
  }, [navigate]);

  useEffect(() => {
    const handleResize = () => setSidebarOpen(window.innerWidth > 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    if (activeTab === 'chat') startChatPolling();
    else stopChatPolling();
    return () => stopChatPolling();
  }, [activeTab, adminChatSession, user, adminChatMode, memberChatMode, adminSelectedMemberEmail]);

  useEffect(() => {
    if (activeTab === 'post' || activeTab === 'career') loadPosts();
    if (activeTab === 'career') loadJobs();
    if (activeTab === 'donation') loadDonations();
  }, [activeTab]);

  const loadPosts = async () => { const fetched = await getBlogPosts(); setPosts(fetched); };
  const loadJobs = async () => { const data = await getJobPosts(); setJobs(data); };
  const loadDonations = async () => { const data = await getDonations(); setDonations(data); };
  const loadNotice = async () => { const notice = await getAdminNotice(); setAdminNotice(notice); setNewNoticeText(notice); };

  const handleUpdateNotice = async () => {
    await updateAdminNotice(newNoticeText);
    setAdminNotice(newNoticeText);
    setIsEditingNotice(false);
    toast.success("Broadcast updated!");
  };

  const startChatPolling = () => { stopChatPolling(); fetchMessages(); chatIntervalRef.current = window.setInterval(fetchMessages, 5000); };
  const stopChatPolling = () => { if (chatIntervalRef.current) { clearInterval(chatIntervalRef.current); chatIntervalRef.current = null; } };

  const getChatSessionID = () => { 
    if (!user) return ''; 
    if (user.role === 'admin') { 
      if (adminChatMode === 'DM') {
        return 'ALL_SUPPORT'; 
      }
      return adminChatSession || ''; 
    } else { 
      // Member Logic
      if (memberChatMode === 'ADMIN') {
        return `SUPPORT_${user.email}`;
      }
      return user.data?.session || ''; 
    } 
  };

  const fetchMessages = async () => { 
    if (!user) return;
    setIsRefreshingChat(true);

    const sessionParam = getChatSessionID(); 
    let batchParam = '';
    if (user.role === 'admin') {
      batchParam = 'ADMIN_VIEW';
    } else if (memberChatMode === 'ADMIN') {
      batchParam = 'SUPPORT';
    } else {
      batchParam = user.data?.batch || '';
    }

    if (sessionParam) {
      const msgs = await getBatchMessages(sessionParam, batchParam);

      if (user.role === 'admin' && adminChatMode === 'DM') {
        // --- MESSENGER LOGIC START (ADMIN) ---
        const convMap: Record<string, ConversationSummary> = {};

        msgs.forEach(msg => {
          if (msg.session && msg.session.startsWith('SUPPORT_')) {
            const userEmail = msg.session.replace('SUPPORT_', '');
            const member = allMembers.find(m => m.email === userEmail);
            const name = member ? member.name : userEmail;
            const photo = member ? (member.photoUrl || '') : '';

            if (!convMap[userEmail]) {
              convMap[userEmail] = {
                email: userEmail,
                name: name,
                photoUrl: photo,
                lastMessage: '',
                timestamp: '',
                unreadCount: 0
              };
            }
            convMap[userEmail].lastMessage = msg.message;
            convMap[userEmail].timestamp = msg.timestamp;
          }
        });

        const convArray = Object.values(convMap);
        convArray.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
        setConversations(convArray);

        if (adminSelectedMemberEmail) {
          const targetSession = `SUPPORT_${adminSelectedMemberEmail}`;
          const currentChat = msgs.filter(m => m.session === targetSession);
          setChatMessages(currentChat.slice(-50).map(m => ({ ...m, isMe: m.senderEmail === user.email })));
        } else {
          setChatMessages([]);
        }
        // --- MESSENGER LOGIC END ---

      } else {
        // Normal Batch Chat Logic (Admin Batch View OR Member View)
        if (msgs) {
           setChatMessages(msgs.map(m => ({ ...m, isMe: m.senderEmail === user.email })));
        }
      }
    }
    setIsRefreshingChat(false);
  };

  const handleLogout = () => { localStorage.removeItem('ssaa_current_user'); window.dispatchEvent(new Event('auth-change')); navigate('/login'); };

  const handleSendMessage = async (e: React.FormEvent) => { 
    e.preventDefault();
    if (!newMessage.trim() || !user) return;
    setIsSendingMsg(true);

    let session = '';
    let batch = '';

    if (user.role === 'admin') {
      if (adminChatMode === 'DM') {
        if (!adminSelectedMemberEmail) { toast.error("Select a conversation"); setIsSendingMsg(false); return; }
        session = `SUPPORT_${adminSelectedMemberEmail}`;
        batch = 'SUPPORT'; // Reply batch context
      } else {
        session = adminChatSession;
        batch = 'ADMIN_REPLY'; // Or just 'ALL'
      }
    } else {
      // Member
      if (memberChatMode === 'ADMIN') {
        session = `SUPPORT_${user.email}`;
        batch = 'SUPPORT';
      } else {
        session = user.data?.session || '';
        batch = user.data?.batch || '';
      }
    }

    if (!session) { toast.error("Select a chat room"); setIsSendingMsg(false); return; }

    const success = await sendChatMessage(session, batch, user.name, user.email, user.data?.photoUrl || '', newMessage);
    if (success) { setNewMessage(''); fetchMessages(); } else { toast.error("Failed to send"); }
    setIsSendingMsg(false);
  };

  const handleStatusUpdate = async (email: string, newStatus: string) => { if (confirm(`Change status to ${newStatus}?`)) { setAllMembers(prev => prev.map(m => m.email === email ? { ...m, status: newStatus as any } : m)); await updateMemberStatus(email, newStatus); } };
  const handleSubmitJob = async (e: React.FormEvent) => { e.preventDefault(); const success = await createJobPost(jobForm.title, jobForm.company, jobForm.deadline, jobForm.link); if (success) { toast.success("Posted!"); setJobForm({ title: '', company: '', deadline: '', link: '' }); loadJobs(); } };

  const handlePostImageChange = (e: React.ChangeEvent<HTMLInputElement>) => { 
    if (e.target.files && e.target.files[0]) {
      setPostForm({...postForm, image: e.target.files[0]});
      setPostImagePreview(URL.createObjectURL(e.target.files[0]));
    }
  };

  const handleEditClick = (post: BlogPost) => { 
    setIsEditingPost(post.id.toString());
    setPostForm({ title: post.title, category: post.category, excerpt: post.excerpt, content: post.content || '', image: null });
    setPostImagePreview(post.imageUrl);
  };

  const handleCancelEdit = () => { 
    setIsEditingPost(null);
    setPostForm({ title: '', category: 'Activity', excerpt: '', content: '', image: null });
    setPostImagePreview(null);
  };

  const handleSubmitPost = async (e: React.FormEvent) => { 
    e.preventDefault();
    setIsPosting(true);
    let success = false;
    if (isEditingPost) {
       success = await updateBlogPost(isEditingPost, postForm.title, postForm.category, postForm.excerpt, postForm.content, postForm.image, postImagePreview || '');
    } else {
       success = await createBlogPost(postForm.title, postForm.category, postForm.excerpt, postForm.content, postForm.image);
    }
    if (success) { toast.success(isEditingPost ? "Updated!" : "Created!"); handleCancelEdit(); loadPosts(); } else { toast.error("Failed"); }
    setIsPosting(false);
  };

  const handleOpenEditProfile = () => { 
    if (user?.data) {
      setEditProfileForm({
        designation: user.data.designation,
        company: user.data.company || '',
        currentAddress: user.data.currentAddress,
        bloodGroup: user.data.bloodGroup || '',
        photo: null,
        dob: user.data.dob || ''
      });
      setEditPhotoPreview(user.data.photoUrl || null);
      setIsEditingProfile(true);
    }
  };

  const handleProfilePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => { 
    if (e.target.files && e.target.files[0]) {
      setEditProfileForm({...editProfileForm, photo: e.target.files[0]});
      setEditPhotoPreview(URL.createObjectURL(e.target.files[0]));
    }
  };

  const handleProfileUpdate = async (e: React.FormEvent) => { 
    e.preventDefault();
    if (!user) return;
    setIsUpdatingProfile(true);
    const success = await updateUserProfile(user.email, editProfileForm.designation, editProfileForm.company, editProfileForm.currentAddress, editProfileForm.bloodGroup, editProfileForm.photo, editProfileForm.dob);
    if (success) {
      toast.success("Profile Updated!");
      setIsEditingProfile(false);
      const updatedUser = { ...user, data: { ...user.data!, ...editProfileForm, photoUrl: editPhotoPreview || user.data!.photoUrl } };
      setUser(updatedUser);
      localStorage.setItem('ssaa_current_user', JSON.stringify(updatedUser));
    } else {
      toast.error("Failed to update profile");
    }
    setIsUpdatingProfile(false);
  };

  const handleDonationStatus = async (id: string, newStatus: string) => {
    if (confirm(`Mark this donation as ${newStatus}?`)) {
      setDonations(prev => prev.map(d => d.id === id ? { ...d, status: newStatus as any } : d));
      const success = await updateDonationStatus(id, newStatus);
      if (success) toast.success(`Donation ${newStatus}`);
      else { toast.error("Failed"); loadDonations(); }
    }
  };

  const getBirthdayMembers = () => {
    const today = new Date();
    const currentMonth = today.getMonth() + 1;
    const currentDate = today.getDate();
    return allMembers.filter(m => {
      if (!m.dob) return false;
      const d = new Date(m.dob);
      return d.getMonth() + 1 === currentMonth; // Same month
    }).sort((a,b) => {
      const da = new Date(a.dob!);
      const db = new Date(b.dob!);
      return da.getDate() - db.getDate();
    });
  };
  const birthdayMembers = getBirthdayMembers();

  const filteredMembers = allMembers.filter(m => (m.email !== 'admin@ssaa.com' && m.email !== 'editor@ssaa.com') && ((bloodFilter === '' || m.bloodGroup === bloodFilter) && (m.name.toLowerCase().includes(searchQuery.toLowerCase()) || m.designation.toLowerCase().includes(searchQuery.toLowerCase()) || m.session.toLowerCase().includes(searchQuery.toLowerCase()) || (m.company && m.company.toLowerCase().includes(searchQuery.toLowerCase())) || m.currentAddress.toLowerCase().includes(searchQuery.toLowerCase()))));

  if (!user) return <div className="flex h-screen items-center justify-center"><Loader2 className="animate-spin text-soil" size={40} /></div>;

  const isValidPhoto = (url?: string) => { return url && url.startsWith('http') && !url.includes('ERROR'); };
  const formatChatDate = (isoString: string) => { 
     try {
       const date = new Date(isoString);
       const day = date.toLocaleString('en-GB', { day: '2-digit' });
       const month = date.toLocaleString('en-GB', { month: 'short' });
       const year = date.toLocaleString('en-GB', { year: 'numeric' });
       const time = date.toLocaleString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true }).toLowerCase();
       return `${day}-${month}-${year} ${time}`;
     } catch { return isoString; }
  };
  const membershipId = user.data?.password || user.password;
  const canPost = user.role === 'admin' || user.role === 'editor';
  const careerPosts = posts.filter(p => p.category === 'Career');
  const visibleDonations = user.role === 'admin' ? donations : donations.filter(d => d.donorEmail === user.email);

  // Helper for Sidebar Date
  const formatShortDate = (iso: string) => {
    try {
      const d = new Date(iso);
      return d.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
    } catch { return ''; }
  };

  return (
    <div className="min-h-screen bg-gray-50 pt-28 pb-4" ref={topRef}>

      {/* 1. ADMIN NOTICE TICKER */}
      {adminNotice && (
        <div className="bg-soil text-white py-2 relative overflow-hidden shadow-md mb-6 mx-4 rounded-lg mt-4">
          <div className="max-w-7xl mx-auto flex items-center px-4">
             <div className="flex items-center font-bold bg-red-600 px-3 py-0.5 rounded mr-2 text-xs uppercase tracking-wider animate-pulse flex-shrink-0">
               <Megaphone size={14} className="mr-1" /> Notice
             </div>
             <div className="flex-grow overflow-hidden relative h-6">
                <div className="whitespace-nowrap absolute animate-marquee left-full">
                  {adminNotice}
                </div>
             </div>
             {user.role === 'admin' && (
               <button onClick={() => setIsEditingNotice(true)} className="ml-2 p-1 hover:bg-white/20 rounded"><Edit size={14} /></button>
             )}
          </div>
        </div>
      )}

      {/* ADMIN EDIT NOTICE MODAL (Inline) */}
      {isEditingNotice && user.role === 'admin' && (
        <div className="fixed inset-0 z-[80] flex items-center justify-center bg-black/50 p-4">
           <div className="bg-white rounded-lg p-6 w-full max-w-md">
              <h3 className="text-lg font-bold mb-4">Update Broadcast Notice</h3>
              <textarea 
                value={newNoticeText} 
                onChange={e => setNewNoticeText(e.target.value)}
                className="w-full border rounded p-2 mb-4 h-24"
                placeholder="Enter notice text..."
              />
              <div className="flex justify-end gap-2">
                <button onClick={() => setIsEditingNotice(false)} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">Cancel</button>
                <button onClick={handleUpdateNotice} className="px-4 py-2 bg-soil text-white rounded hover:bg-soil-dark">Update</button>
              </div>
           </div>
        </div>
      )}

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {user.role === 'member' && (
          <div className="text-center mb-8">
            <h2 className="text-3xl md:text-4xl font-serif font-bold text-soil tracking-wide inline-block relative pb-3">Proud Alumni<span className="absolute bottom-0 left-1/2 transform -translate-x-1/2 w-24 h-1 bg-leaf rounded-full"></span></h2>
          </div>
        )}

        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-4 md:p-8 mb-6 md:mb-8 flex flex-col md:flex-row items-center md:justify-between gap-4 md:gap-6">
          {/* Header Content... */}
          <div className="flex flex-col sm:flex-row items-center gap-4 md:gap-6 text-center sm:text-left">
            <div className="w-20 h-20 md:w-24 md:h-24 rounded-full border-4 border-white shadow-lg overflow-hidden bg-gray-200 flex-shrink-0">
               {isValidPhoto(user.data?.photoUrl) ? (<img src={user.data!.photoUrl} alt={user.name} className="w-full h-full object-cover" />) : (<div className="w-full h-full flex items-center justify-center bg-soil text-white text-3xl font-bold">{user.name.charAt(0)}</div>)}
            </div>
            <div>
              <h1 className="text-2xl md:text-3xl font-bold text-gray-900">{user.name}</h1>
              <div className="flex items-center justify-center sm:justify-start gap-2 mt-2 flex-wrap">
                 {user.role === 'admin' ? (<span className="px-3 py-1 rounded-full text-xs font-semibold bg-purple-100 text-purple-700">Administrator</span>) : user.role === 'editor' ? (<span className="px-3 py-1 rounded-full text-xs font-semibold bg-blue-100 text-blue-700">Content Editor</span>) : membershipId ? (<span className="px-3 py-1 rounded-full text-xs font-semibold bg-green-100 text-green-700">Membership ID: {membershipId}</span>) : null}
                 {user.data?.batch && <span className="text-gray-500 text-sm">| Batch {user.data?.batch}</span>}
              </div>
            </div>
          </div>

          <div className="flex bg-gray-100 p-1 rounded-lg self-center md:self-auto mt-4 md:mt-0 overflow-x-auto max-w-full w-full md:w-auto">
             {user.role === 'admin' && (<button onClick={() => setActiveTab('admin')} className={`px-4 py-2 rounded-md text-sm font-medium transition-all whitespace-nowrap flex-shrink-0 ${activeTab === 'admin' ? 'bg-white text-soil shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>All Members</button>)}
             {user.role === 'admin' && (<button onClick={() => setActiveTab('donation')} className={`px-4 py-2 rounded-md text-sm font-medium transition-all whitespace-nowrap flex-shrink-0 ${activeTab === 'donation' ? 'bg-white text-soil shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>Donations</button>)}
             {(user.role === 'admin' || user.role === 'member') && (<button onClick={() => setActiveTab('chat')} className={`px-4 py-2 rounded-md text-sm font-medium transition-all whitespace-nowrap flex-shrink-0 ${activeTab === 'chat' ? 'bg-white text-soil shadow-sm' : 'text-gray-500 hover:text-gray-700'} flex items-center`}><MessageCircle size={16} className="mr-2" /> {user.role === 'admin' ? 'Chats' : 'Chat'}</button>)}
             {canPost && (<button onClick={() => setActiveTab('post')} className={`px-4 py-2 rounded-md text-sm font-medium transition-all whitespace-nowrap flex-shrink-0 ${activeTab === 'post' ? 'bg-white text-soil shadow-sm' : 'text-gray-500 hover:text-gray-700'} flex items-center`}><PenTool size={16} className="mr-2" /> Content</button>)}
             <button onClick={() => setActiveTab('profile')} className={`px-4 py-2 rounded-md text-sm font-medium transition-all whitespace-nowrap flex-shrink-0 ${activeTab === 'profile' ? 'bg-white text-soil shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>My Profile</button>
             {user.role === 'member' && (
               <>
               <button onClick={() => setActiveTab('career')} className={`px-4 py-2 rounded-md text-sm font-medium transition-all whitespace-nowrap flex-shrink-0 ${activeTab === 'career' ? 'bg-white text-soil shadow-sm' : 'text-gray-500 hover:text-gray-700'} flex items-center`}><Briefcase size={16} className="mr-2" /> Career</button>
               <button onClick={() => setActiveTab('search')} className={`px-4 py-2 rounded-md text-sm font-medium transition-all whitespace-nowrap flex-shrink-0 ${activeTab === 'search' ? 'bg-white text-soil shadow-sm' : 'text-gray-500 hover:text-gray-700'} flex items-center`}><Search size={16} className="mr-2" /> Search</button>
               <button onClick={() => setActiveTab('donation')} className={`px-4 py-2 rounded-md text-sm font-medium transition-all whitespace-nowrap flex-shrink-0 ${activeTab === 'donation' ? 'bg-white text-soil shadow-sm' : 'text-gray-500 hover:text-gray-700'} flex items-center`}><Heart size={16} className="mr-2" /> Donate</button>
               </>
             )}
          </div>
        </div>

        {/* PROFILE VIEW WITH WIDGETS */}
        {activeTab === 'profile' && user.data && (
           <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
             {/* LEFT COLUMN: Personal Info & Widgets */}
             <div className="col-span-1 space-y-6">
               {/* Personal Info Card */}
               <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
                 <div className="flex justify-between items-start mb-4"><h3 className="font-bold text-lg text-gray-900">Personal Info</h3><button onClick={handleOpenEditProfile} className="text-leaf hover:text-leaf-dark p-2 bg-leaf/10 rounded-full transition-colors"><Edit size={16} /></button></div>
                 <div className="space-y-4">
                   <div className="flex items-center text-gray-600"><Mail size={18} className="mr-3" /> {user.email}</div>
                   <div className="flex items-center text-gray-600"><Phone size={18} className="mr-3" /> {user.data.phone}</div>
                   <div className="flex items-center text-gray-600"><MapPin size={18} className="mr-3" /> {user.data.currentAddress}</div>
                   <div className="flex items-center text-gray-600"><Heart size={18} className="mr-3 text-red-500" /> Blood Group: {user.data.bloodGroup || 'N/A'}</div>
                   {user.data.dob && <div className="flex items-center text-gray-600"><Gift size={18} className="mr-3 text-pink-500" /> DOB: {user.data.dob}</div>}
                 </div>
               </div>

               {/* 2. BIRTHDAY CORNER WIDGET */}
               <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
                  <h3 className="font-bold text-lg text-gray-900 mb-4 flex items-center text-pink-600"><Gift size={20} className="mr-2"/> Birthday Corner</h3>
                  {birthdayMembers.length > 0 ? (
                    <div className="space-y-4">
                      {birthdayMembers.map((m, idx) => {
                         const isToday = new Date().getDate() === new Date(m.dob!).getDate();
                         return (
                           <div key={idx} className={`flex items-center gap-3 p-3 rounded-lg ${isToday ? 'bg-pink-50 border border-pink-100' : 'bg-gray-50'}`}>
