cerpt: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-soil focus:border-transparent outline-none bg-white text-gray-900" /></div><div><label className="block text-sm font-medium text-gray-700 mb-1">Full Content</label><textarea rows={6} value={postForm.content} onChange={e => setPostForm({...postForm, content: e.target.value})} className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-soil focus:border-transparent outline-none bg-white text-gray-900" /></div><div className="pt-4 flex justify-end"><button type="submit" disabled={isPosting} className="bg-leaf hover:bg-leaf-dark text-white px-8 py-3 rounded-full font-bold shadow-md hover:shadow-lg transition-all flex items-center">{isPosting ? <RefreshCw className="animate-spin mr-2" /> : <Send className="mr-2" />}{isEditingPost ? 'Update Post' : 'Publish Post'}</button></div></form></div>
