// Helper to handle Google Script API calls with Retry Logic
const callScript = async (action: string, payload: any = {}, retries = 2) => {
  if (!GOOGLE_SCRIPT_URL) throw new Error("No Script URL Configuration");

  for (let i = 0; i <= retries; i++) {
    try {
      const response = await fetch(GOOGLE_SCRIPT_URL, {
        method: 'POST',
        redirect: "follow", 
        headers: {
          "Content-Type": "text/plain;charset=utf-8", 
        },
        body: JSON.stringify({ action, ...payload })
      });

      if (!response.ok) {
        throw new Error(`Server responded with ${response.status}`);
      }

      const text = await response.text();
      try {
        const json = JSON.parse(text);
        if (json.result === 'error') {
           throw new Error(json.error);
        }
        return json;
      } catch (e: any) {
        if (text.includes("<!DOCTYPE html>") || text.includes("Google Drive") || text.includes("script.google.com")) {
           throw new Error("Access Blocked. Script must be deployed as 'Web App' with 'Who has access: Anyone'.");
        }
        if (e.message && !e.message.includes("JSON")) throw e;
        throw new Error(`Invalid Server Response: ${text.substring(0, 50)}...`); 
      }
    } catch (error: any) {
      const isLastAttempt = i === retries;
      if (!isLastAttempt) {
        await new Promise(res => setTimeout(res, 1500));
        continue;
      }
      console.warn(`API Call Failed (Attempt ${i+1}/${retries+1}):`, error.message);
      if (error.message === 'Failed to fetch' || error.name === 'TypeError') {
         throw new Error("Network Connection Failed. Please check your internet or the Script Deployment.");
      }
      throw error;
    }
  }
};

const uploadToImgBB = async (file: File): Promise<string> => {
  const key = IMGBB_API_KEY || "a720709745d21ff017681904fc484d8c";
  const formData = new FormData();
  formData.append("image", file);
  try {
    const response = await fetch(`https://api.imgbb.com/1/upload?key=${key}`, { method: "POST", body: formData });
    const result = await response.json();
    if (result.success) return result.data.url;
    else throw new Error("ImgBB Error: " + (result.error?.message || "Unknown"));
  } catch (err) {
    throw new Error("Image Upload Failed. Check internet connection.");
  }
};

export const sendVerificationEmail = async (email: string, otp: string): Promise<boolean> => {
  if (GOOGLE_SCRIPT_URL && GOOGLE_SCRIPT_URL.includes('script.google.com')) {
    try {
      console.log(`Sending OTP to ${email}...`);
      const response = await callScript('sendEmail', { email, otp });
      if (response.result === 'success') return true;
      throw new Error(response.error || "Unknown Backend Error");
    } catch (error: any) {
      console.warn("Email sending error:", error);
      let msg = "Email delivery failed.";
      if (error.message.includes("permission") || error.message.includes("Access")) msg = "System Permission Error (Backend).";
      else if (error.message.includes("quota")) msg = "Daily Email Limit Reached.";
      else if (error.message.includes("Network")) msg = "Network Connection Issue.";
      alert(`[System Message] ${msg}\n\nWelcome to Soil Science Alumni Association!\nYour email Verification OTP code is: ${otp}`);
      return true;
    }
  }
  alert(`[Dev Mode] No Script URL configured.\n\nWelcome to Soil Science Alumni Association!\nYour email Verification OTP code is: ${otp}`);
  return true;
};

export const submitRegistration = async (data: AlumniRegistrationData): Promise<boolean> => {
  let photoUrl = "";
  if (data.photo) {
    try {
      photoUrl = await uploadToImgBB(data.photo);
    } catch (imgError: any) {
      console.error("Image Upload Failed", imgError);
      if (!confirm("Image upload failed. Do you want to register without a photo?")) {
        throw new Error("Registration cancelled by user.");
      }
    }
  }
  if (GOOGLE_SCRIPT_URL && GOOGLE_SCRIPT_URL.includes('script.google.com')) {
    try {
      const { photo, password, ...dataToSend } = data;
      const payload = { ...dataToSend, photoUrl: photoUrl };
      const result = await callScript('register', { data: payload });
      if (result.result === 'success') return true;
      else throw new Error("Google Script Error: " + (result.error || "Unknown"));
    } catch (error: any) {
      console.error("Online Registration Failed:", error);
      alert("Warning: Connection to Server Failed.\n\nYour data has been saved locally for now, but you may need to register again later when online.");
    }
  }
  saveToLocalFallback(data, photoUrl);
  return true;
};

const saveToLocalFallback = (data: AlumniRegistrationData, photoUrl: string) => {
  const users = getLocalUsers();
  const { photo, password, ...safeData } = data;
  const newUser = {
    ...safeData,
    company: data.company || '',
    bloodGroup: data.bloodGroup || '',
    status: 'Pending' as const,
    registrationDate: new Date().toISOString().split('T')[0],
    photoUrl: photoUrl || `https://ui-avatars.com/api/?background=random&name=${encodeURIComponent(data.name)}`
  };
  users.push(newUser as AlumniRegistrationData);
  localStorage.setItem(STORAGE_KEY, JSON.stringify(users));
  const currentCount = parseInt(localStorage.getItem('ssaa_alumni_count') || '0');
  localStorage.setItem('ssaa_alumni_count', (currentCount + 1).toString());
};

const getLocalUsers = (): AlumniRegistrationData[] => {
  const stored = localStorage.getItem(STORAGE_KEY);
  return stored ? JSON.parse(stored) : INITIAL_MOCK_USERS;
};

export const fetchStats = async (): Promise<{ alumniCount: number; activityCount: number }> => {
  if (GOOGLE_SCRIPT_URL && GOOGLE_SCRIPT_URL.includes('script.google.com')) {
    try {
      const response = await callScript('getStats');
      if (response && response.stats) {
        localStorage.setItem('ssaa_alumni_count', response.stats.alumniCount.toString());
        return response.stats;
      }
    } catch (e) { console.warn("Stats fetch failed"); }
  }
  // Return 0 if failed so it doesn't show confusing mock data
  return { alumniCount: 0, activityCount: 0 };
};

export const loginUser = async (email: string, membershipId: string): Promise<User | null> => {
  if (GOOGLE_SCRIPT_URL && GOOGLE_SCRIPT_URL.includes('script.google.com')) {
    try {
      const response = await callScript('login', { email, password: membershipId });
      if (response.success && response.user) {
        if (response.user.password && response.user.data) {
          response.user.data.password = response.user.password;
        }
        return {
          ...response.user,
          role: response.user.role || (response.user.email === 'admin@ssaa.com' ? 'admin' : 'member')
        };
      } else {
        // If server responded but returned an error (e.g., account not found/approved), throw it.
        if (response.error) throw new Error(response.error);
        return null;
      }
    } catch (e: any) {
      console.error("Login API Error:", e);
      // Only throw if it's a specific logic error from the server
      const msg = e.message.toLowerCase();
      if (msg.includes("invalid") || msg.includes("account not approved") || msg.includes("not found") || msg.includes("password")) {
         throw e;
      }
      // If it's a network error (e.g. "Network Connection Failed"), log warning and fall through to local login
      console.warn("API unavailable, attempting local login...");
    }
  }

  // Local Fallback Logic
  return new Promise((resolve) => {
    setTimeout(() => {
      const users = getLocalUsers();
      const foundUser = users.find(u => u.email === email && u.password === membershipId);
      if (foundUser) {
        let role: 'admin' | 'member' | 'editor' = 'member';
        if (foundUser.email === 'admin@ssaa.com') role = 'admin';
        if (foundUser.email === 'editor@ssaa.com') role = 'editor';
        resolve({ email: foundUser.email, name: foundUser.name, role: role, data: foundUser });
      } else {
        resolve(null);
      }
    }, 1000);
  });
};

