  if (GOOGLE_SCRIPT_URL && GOOGLE_SCRIPT_URL.includes('script.google.com')) {
    try {
      // Use 0 retries for notice fetch to ensure dashboard loads fast even if backend is slow
      const response = await callScript('getNotice', {}, 0);
      if (response && response.notice) {
        localStorage.setItem(NOTICE_KEY, response.notice);
        return response.notice;
      }
    } catch(e) {
      console.debug("Notice fetch skipped (using local):", e);
    }
  }
  return localStorage.getItem(NOTICE_KEY) || "Welcome to SSAA Dashboard! New Alumni Registration is open now.";
};

export const updateAdminNotice = async (notice: string): Promise<boolean> => {
  // 1. Update Local Storage Immediately for instant UI feedback
  localStorage.setItem(NOTICE_KEY, notice);

  // 2. Try Sync to Server
  if (GOOGLE_SCRIPT_URL && GOOGLE_SCRIPT_URL.includes('script.google.com')) {
     try {
       await callScript('updateNotice', { notice }, 0); // 0 retries
     } catch (e) {
       // Warn instead of error so it doesn't look like a crash to the user/developer console
       console.warn("Notice synced locally only (Server update failed or not supported).");
     }
  }
  return true;
};

