  // Admin Chat State
  const [adminChatSession, setAdminChatSession] = useState<string>(''); 
  const [adminChatMode, setAdminChatMode] = useState<'BATCH' | 'DM'>('BATCH');
  const [adminSelectedMemberEmail, setAdminSelectedMemberEmail] = useState<string>('');
  const [conversations, setConversations] = useState<ConversationSummary[]>([]); // New: For Messenger Sidebar

  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatIntervalRef = useRef<number | null>(null);

  // Post State
  const [posts, setPosts] = useState<BlogPost[]>([]);
  const [isEditingPost, setIsEditingPost] = useState<string | null>(null);
  const [postForm, setPostForm] = useState({ title: '', category: 'Activity', excerpt: '', content: '', image: null as File | null });
  const [postImagePreview, setPostImagePreview] = useState<string | null>(null);
  const [isPosting, setIsPosting] = useState(false);

  // Job State
  const [jobs, setJobs] = useState<JobPost[]>([]);
  const [jobForm, setJobForm] = useState({ title: '', company: '', deadline: '', link: '' });

  // Search State
