      loadNotice();
    };
    checkAuth();
    return () => stopChatPolling();
  }, [navigate]);

  useEffect(() => {
    const handleResize = () => setSidebarOpen(window.innerWidth > 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    if (activeTab === 'chat') startChatPolling();
    else stopChatPolling();
    return () => stopChatPolling();
  }, [activeTab, adminChatSession, user, adminChatMode, memberChatMode, adminSelectedMemberEmail]);

  useEffect(() => {
    if (activeTab === 'post' || activeTab === 'career') loadPosts();
    if (activeTab === 'career') loadJobs();
    if (activeTab === 'donation') loadDonations();
  }, [activeTab]);

