  const handleSubmitJob = async (e: React.FormEvent) => { e.preventDefault(); const success = await createJobPost(jobForm.title, jobForm.company, jobForm.deadline, jobForm.link); if (success) { toast.success("Posted!"); setJobForm({ title: '', company: '', deadline: '', link: '' }); loadJobs(); } };

