     try {
       const date = new Date(isoString);
       const day = date.toLocaleString('en-GB', { day: '2-digit' });
       const month = date.toLocaleString('en-GB', { month: 'short' });
       const year = date.toLocaleString('en-GB', { year: 'numeric' });
       const time = date.toLocaleString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true }).toLowerCase();
       return `${day}-${month}-${year} ${time}`;
     } catch { return isoString; }
  };
  const membershipId = user.data?.password || user.password;
  const canPost = user.role === 'admin' || user.role === 'editor';
  const careerPosts = posts.filter(p => p.category === 'Career');
