                       <td className="px-6 py-4"><div className="flex items-center"><div className="w-8 h-8 rounded-full border border-gray-200 overflow-hidden mr-3 bg-gray-100 flex-shrink-0">{isValidPhoto(member.photoUrl) ? (<img src={member.photoUrl} alt="" className="w-full h-full object-cover" />) : (<div className="w-full h-full flex items-center justify-center bg-soil text-white text-xs font-bold">{member.name.charAt(0)}</div>)}</div><div><p className="font-semibold text-gray-900">{member.name}</p><p className="text-xs text-gray-500">Session: {member.session}</p></div></div></td>
                       <td className="px-6 py-4 text-gray-700">{member.batch}</td>
                       <td className="px-6 py-4"><p className="text-sm text-gray-900">{member.email}</p><p className="text-xs text-gray-500">{member.phone}</p></td>
                       <td className="px-6 py-4 text-gray-700 max-w-xs truncate" title={member.designation}>{member.designation}</td>
                       <td className="px-6 py-4">
                         {user.role === 'admin' ? (
                           <select value={member.status || 'Pending'} onChange={(e) => handleStatusUpdate(member.email, e.target.value)} className={`block w-full text-xs font-semibold px-2 py-1 rounded-full border-none focus:ring-2 focus:ring-offset-1 focus:ring-soil cursor-pointer outline-none ${member.status === 'Approved' ? 'bg-green-100 text-green-800' : member.status === 'Rejected' ? 'bg-red-100 text-red-800' : 'bg-yellow-100 text-yellow-800'}`}><option value="Pending">Pending</option><option value="Approved">Approved</option><option value="Rejected">Rejected</option></select>
                         ) : (
                           <span className={`px-2 py-1 rounded-full text-xs font-bold ${member.status === 'Approved' ? 'bg-green-100 text-green-700' : member.status === 'Rejected' ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'}`}>{member.status}</span>
                         )}
                       </td>
                     </tr>
                   ))}
                 </tbody>
               </table>
             </div>
          </div>
        )}

        {/* SEARCH DIRECTORY */}
        {activeTab === 'search' && (
          <div className="space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex flex-col md:flex-row gap-4 items-center">
              <div className="relative flex-grow w-full">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                <input type="text" placeholder="Search alumni by Name, Designation, Company or City..." className="w-full pl-10 pr-4 py-3 border rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white text-gray-900" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
              </div>
              <div className="flex gap-2 w-full md:w-auto">
                <select value={bloodFilter} onChange={(e) => setBloodFilter(e.target.value)} className="w-full md:w-40 px-4 py-3 border rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white text-gray-900">
                  <option value="">All Blood</option>
                  {['A+','A-','B+','B-','AB+','AB-','O+','O-'].map(b=><option key={b} value={b}>{b}</option>)}
                </select>
                <button 
                  onClick={() => setShowMentorsOnly(!showMentorsOnly)}
                  className={`px-4 py-3 rounded-lg border font-medium flex items-center transition-all whitespace-nowrap ${showMentorsOnly ? 'bg-indigo-100 border-indigo-200 text-indigo-700' : 'bg-white border-gray-200 text-gray-600 hover:bg-gray-50'}`}
                >
                  <Star size={16} className={`mr-1 ${showMentorsOnly ? 'fill-current' : ''}`} />
                  {showMentorsOnly ? 'Mentors' : 'Mentors'}
                </button>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredMembers.length > 0 ? filteredMembers.map((member, idx) => (
                <div key={idx} className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 hover:border-leaf transition-colors flex items-center gap-4 relative overflow-hidden">
                  {member.isMentor && (
                    <div className="absolute top-0 right-0 bg-indigo-500 text-white text-[10px] px-2 py-1 font-bold rounded-bl-lg shadow-sm">
                      MENTOR
                    </div>
                  )}
                  <div className="w-16 h-16 rounded-full bg-gray-100 overflow-hidden flex-shrink-0 border-2 border-white shadow-sm">
                    {isValidPhoto(member.photoUrl) ? <img src={member.photoUrl} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center font-bold text-gray-400">{member.name.charAt(0)}</div>}
                  </div>
                  <div className="overflow-hidden w-full">
                    <h4 className="font-bold text-gray-900 truncate flex items-center">
                      {member.name}
                      {member.isMentor && <Star size={12} className="ml-1 text-indigo-500 fill-current" />}
                    </h4>
                    <p className="text-xs text-gray-500 font-medium mb-1">Session: {member.session}</p>
                    <p className="text-sm text-soil truncate font-medium">{member.designation}</p>
                    {member.company && <p className="text-xs text-gray-600 truncate">@ {member.company}</p>}
                    {member.bloodGroup && <span className="inline-block mt-1 text-[10px] bg-red-100 text-red-700 px-2 py-0.5 rounded font-bold">{member.bloodGroup}</span>}
                  </div>
                </div>
              )) : <p className="col-span-3 text-center text-gray-500 py-10">No alumni found matching your search.</p>}
            </div>
          </div>
        )}

        {/* DONATION */}
        {activeTab === 'donation' && (
          <div className="space-y-8">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
              <h3 className="text-2xl font-bold text-gray-900 flex items-center"><DollarSign className="mr-2 text-leaf" /> {user.role === 'admin' ? 'Donation Management' : 'My Donation History'}</h3>
              <div className="flex gap-3">
                 {user.role === 'member' && (
                   <button onClick={() => openModal('donation')} className="bg-soil hover:bg-soil-dark text-white px-5 py-2.5 rounded-full font-bold shadow-md transition-all flex items-center transform hover:scale-105">
                     <Heart size={18} className="mr-2 text-pink-400 fill-current" /> Donate Now
                   </button>
                 )}
                 {user.role === 'admin' && <button onClick={loadDonations} className="text-sm text-gray-500 flex items-center bg-gray-100 px-3 py-2 rounded-lg hover:bg-gray-200"><RefreshCw size={14} className="mr-1" /> Refresh</button>}
              </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead><tr className="bg-gray-100 text-gray-600 text-sm uppercase tracking-wider"><th className="px-6 py-4 font-semibold">Date</th><th className="px-6 py-4 font-semibold">Donor</th><th className="px-6 py-4 font-semibold">Amount</th><th className="px-6 py-4 font-semibold">Details</th><th className="px-6 py-4 font-semibold">Status</th>{user.role === 'admin' && <th className="px-6 py-4 font-semibold text-right">Action</th>}</tr></thead>
                  <tbody className="divide-y divide-gray-100">
                    {visibleDonations.length > 0 ? visibleDonations.map((d) => (
                      <tr key={d.id} className="hover:bg-gray-50 transition-colors">
                        <td className="px-6 py-4 text-sm text-gray-500 whitespace-nowrap">{new Date(d.date).toLocaleDateString()}</td>
                        <td className="px-6 py-4"><p className="font-semibold text-gray-900">{d.donorName}</p><p className="text-xs text-gray-500">{d.donorEmail}</p></td>
                        <td className="px-6 py-4 font-bold text-soil">{d.amount} BDT</td>
                        <td className="px-6 py-4 text-sm text-gray-600"><p><span className="font-medium">Via:</span> {d.method}</p><p><span className="font-medium">Acc:</span> {d.accountNumber}</p><p><span className="font-medium">TrxID:</span> {d.trxId}</p></td>
                        <td className="px-6 py-4"><span className={`px-2 py-1 rounded-full text-xs font-bold ${d.status === 'Approved' ? 'bg-green-100 text-green-700' : d.status === 'Rejected' ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'}`}>{d.status}</span></td>
                        {user.role === 'admin' && (<td className="px-6 py-4 text-right">{d.status === 'Pending' && (<div className="flex justify-end gap-2"><button onClick={() => handleDonationStatus(d.id, 'Approved')} className="text-green-600 hover:bg-green-50 p-1 rounded" title="Approve"><Check size={18} /></button><button onClick={() => handleDonationStatus(d.id, 'Rejected')} className="text-red-600 hover:bg-red-50 p-1 rounded" title="Reject"><XIcon size={18} /></button></div>)}</td>)}
                      </tr>
                    )) : (<tr><td colSpan={user.role === 'admin' ? 6 : 5} className="px-6 py-8 text-center text-gray-500">No donation records found.</td></tr>)}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {/* CAREER */}
        {activeTab === 'career' && (
          <div className="space-y-8">
            <h3 className="text-2xl font-bold text-gray-900 flex items-center"><Briefcase className="mr-2 text-soil" /> Career Opportunities</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {careerPosts.length > 0 ? careerPosts.map(post => (
                <div key={post.id} className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 hover:shadow-md transition-all">
                  <div className="flex justify-between items-start"><div><h4 className="text-xl font-bold text-gray-900 line-clamp-2">{post.title}</h4><p className="text-soil font-medium text-sm mt-1">{post.category}</p></div><span className="text-xs bg-gray-100 text-gray-600 px-2 py-1 rounded whitespace-nowrap">{formatDate(post.date)}</span></div>
                  <p className="text-gray-600 text-sm mt-3 line-clamp-3">{post.excerpt}</p>
                  <div className="mt-4 pt-4 border-t border-gray-50 flex justify-end"><span className="text-xs text-gray-400 italic">Check Home page for full details</span></div>
                </div>
              )) : <p className="col-span-2 text-center text-gray-500 py-10">No job circulars posted yet.</p>}
            </div>
          </div>
        )}

        {/* POST */}
        {activeTab === 'post' && canPost && (
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
              <div className="p-6 border-b border-gray-100 bg-gray-50 flex justify-between items-center"><h3 className="text-lg font-bold text-gray-900 flex items-center"><PenTool className="mr-2 text-soil" /> {isEditingPost ? 'Edit Post' : 'Create New Post'}</h3>{isEditingPost && (<button onClick={handleCancelEdit} className="text-sm text-red-600 hover:text-red-800 flex items-center"><XIcon size={16} className="mr-1" /> Cancel Edit</button>)}</div>
              <div className="p-8"><form onSubmit={handleSubmitPost} className="space-y-6 max-w-3xl mx-auto"><div className="grid grid-cols-1 md:grid-cols-2 gap-6"><div className="col-span-2"><label className="block text-sm font-medium text-gray-700 mb-1">Post Title</label><input required type="text" value={postForm.title} onChange={e => setPostForm({...postForm, title: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-soil focus:border-transparent outline-none bg-white text-gray-900" placeholder="e.g. Job Circular / Event" /></div><div><label className="block text-sm font-medium text-gray-700 mb-1">Category</label><select value={postForm.category} onChange={e => setPostForm({...postForm, category: e.target.value as any})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-soil focus:border-transparent outline-none bg-white text-gray-900"><option value="Activity">Recent Activity</option><option value="Success">Alumni Success</option><option value="News">General News</option><option value="Career">Career / Job</option></select></div><div><label className="block text-sm font-medium text-gray-700 mb-1">{isEditingPost ? 'Update Image' : 'Featured Image'}</label><div className="flex items-center gap-4"><label className="cursor-pointer bg-gray-100 hover:bg-gray-200 text-gray-600 px-4 py-2 rounded-lg text-sm font-medium flex items-center transition-colors"><Upload size={16} className="mr-2" /> Upload Photo<input type="file" className="hidden" accept="image/*" onChange={handlePostImageChange} /></label>{postImagePreview && (<div className="h-10 w-10 rounded overflow-hidden border border-gray-200"><img src={postImagePreview} alt="Preview" className="w-full h-full object-cover" /></div>)}</div></div></div><div><label className="block text-sm font-medium text-gray-700 mb-1">Short Excerpt</label><textarea required rows={2} value={postForm.excerpt} onChange={e => setPostForm({...postForm, excerpt: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-soil focus:border-transparent outline-none bg-white text-gray-900" /></div><div><label className="block text-sm font-medium text-gray-700 mb-1">Full Content</label><textarea rows={6} value={postForm.content} onChange={e => setPostForm({...postForm, content: e.target.value})} className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-soil focus:border-transparent outline-none bg-white text-gray-900" /></div><div className="pt-4 flex justify-end"><button type="submit" disabled={isPosting} className="bg-leaf hover:bg-leaf-dark text-white px-8 py-3 rounded-full font-bold shadow-md hover:shadow-lg transition-all flex items-center">{isPosting ? <RefreshCw className="animate-spin mr-2" /> : <Send className="mr-2" />}{isEditingPost ? 'Update Post' : 'Publish Post'}</button></div></form></div>
              <div className="p-6 border-t border-gray-100"><div className="flex justify-between items-center mb-4"><h3 className="text-lg font-bold text-gray-900">Manage Posts</h3><button onClick={loadPosts} className="text-sm text-gray-500 hover:text-gray-700 flex items-center"><RefreshCw size={14} className="mr-1" /> Refresh List</button></div><div className="overflow-x-auto"><table className="w-full text-left border-collapse"><thead><tr className="bg-gray-100 text-gray-600 text-sm uppercase tracking-wider"><th className="px-6 py-4 font-semibold">Title</th><th className="px-6 py-4 font-semibold">Category</th><th className="px-6 py-4 font-semibold text-right">Actions</th></tr></thead><tbody className="divide-y divide-gray-100">{posts.length > 0 ? posts.map((post) => (<tr key={post.id} className="hover:bg-gray-50 transition-colors"><td className="px-6 py-4 font-medium text-gray-900">{post.title}</td><td className="px-6 py-4"><span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${post.category === 'Career' ? 'bg-purple-100 text-purple-800' : post.category === 'Activity' ? 'bg-blue-100 text-blue-800' : 'bg-gray-100 text-gray-800'}`}>{post.category}</span></td><td className="px-6 py-4 text-right"><button onClick={() => handleEditClick(post)} className="text-soil hover:text-soil-dark font-medium text-sm flex items-center justify-end"><Edit size={16} className="mr-1" /> Edit</button></td></tr>)) : <tr><td colSpan={3} className="px-6 py-8 text-center text-gray-500">No posts found.</td></tr>}</tbody></table></div></div>
          </div>
        )}

      </div>

      {/* Edit Profile Modal */}
      {isEditingProfile && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4">
          <div className="bg-white rounded-xl shadow-xl w-full max-w-lg overflow-hidden max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-gray-50 sticky top-0 z-10">
              <h3 className="text-lg font-bold text-gray-900">Edit Profile</h3>
              <button onClick={() => setIsEditingProfile(false)} className="text-gray-500 hover:text-gray-700"><XIcon size={20} /></button>
            </div>
            <form onSubmit={handleProfileUpdate} className="p-6 space-y-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Profile Picture</label>
                <div className="flex items-center gap-4">
                  <div className="w-16 h-16 rounded-full border border-gray-200 overflow-hidden bg-gray-100">{editPhotoPreview ? (<img src={editPhotoPreview} alt="Preview" className="w-full h-full object-cover" />) : (<div className="w-full h-full flex items-center justify-center bg-soil text-white text-xl font-bold">P</div>)}</div>
                  <label className="cursor-pointer bg-white border border-gray-300 text-gray-700 px-4 py-2 rounded-lg text-sm font-medium hover:bg-gray-50 transition-colors">Change Photo<input type="file" className="hidden" accept="image/*" onChange={handleProfilePhotoChange} /></label>
                </div>
              </div>

              {/* MENTOR TOGGLE */}
              <div className="bg-indigo-50 p-4 rounded-lg border border-indigo-100 flex items-start gap-3">
                 <input 
                   type="checkbox" 
                   id="isMentor"
                   checked={editProfileForm.isMentor}
                   onChange={e => setEditProfileForm({...editProfileForm, isMentor: e.target.checked})}
                   className="mt-1 w-4 h-4 text-indigo-600 rounded focus:ring-indigo-500"
                 />
                 <div>
                    <label htmlFor="isMentor" className="block text-sm font-bold text-indigo-900 cursor-pointer">Available for Mentorship</label>
                    <p className="text-xs text-indigo-700 mt-1">Check this if you are willing to guide junior alumni or students with career advice.</p>
                 </div>
              </div>

              <div><label className="block text-sm font-medium text-gray-700 mb-1">Current Designation</label><input required type="text" value={editProfileForm.designation} onChange={e => setEditProfileForm({...editProfileForm, designation: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-soil focus:border-transparent outline-none bg-white text-gray-900" /></div>
              <div><label className="block text-sm font-medium text-gray-700 mb-1">Company/Organization</label><input type="text" value={editProfileForm.company} onChange={e => setEditProfileForm({...editProfileForm, company: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-soil focus:border-transparent outline-none bg-white text-gray-900" /></div>
              <div><label className="block text-sm font-medium text-gray-700 mb-1">Blood Group</label><select value={editProfileForm.bloodGroup} onChange={e => setEditProfileForm({...editProfileForm, bloodGroup: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-soil focus:border-transparent outline-none bg-white text-gray-900"><option value="">Select...</option>{['A+','A-','B+','B-','AB+','AB-','O+','O-'].map(b=><option key={b} value={b}>{b}</option>)}</select></div>
              <div><label className="block text-sm font-medium text-gray-700 mb-1">Date of Birth</label><input type="date" value={editProfileForm.dob} onChange={e => setEditProfileForm({...editProfileForm, dob: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-soil focus:border-transparent outline-none bg-white text-gray-900" /></div>
              <div><label className="block text-sm font-medium text-gray-700 mb-1">Current Address</label><textarea required rows={2} value={editProfileForm.currentAddress} onChange={e => setEditProfileForm({...editProfileForm, currentAddress: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-soil focus:border-transparent outline-none bg-white text-gray-900" /></div>
              <div className="flex justify-end pt-2"><button type="button" onClick={() => setIsEditingProfile(false)} className="mr-3 px-4 py-2 text-gray-700 font-medium hover:bg-gray-100 rounded-lg transition-colors">Cancel</button><button type="submit" disabled={isUpdatingProfile} className="px-6 py-2 bg-leaf text-white font-medium rounded-lg hover:bg-leaf-dark flex items-center shadow-sm disabled:opacity-70">{isUpdatingProfile ? <RefreshCw className="animate-spin mr-2 w-4 h-4" /> : null} Save Changes</button></div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

export interface BlogPost {
  id: string | number;
  title: string;
  excerpt: string;
  category: 'Activity' | 'Success' | 'News' | 'Career';
  date: string;
  imageUrl: string;
  content?: string;
}

