      }
    }
  };

  return (
    <nav className={`fixed w-full z-50 transition-all duration-300 ${scrolled ? 'bg-white dark:bg-dark-card shadow-lg py-1' : 'bg-white/95 dark:bg-dark-bg/95 backdrop-blur-sm py-1 shadow-sm'}`}>
