// Animated Counter Component
const AnimatedCounter: React.FC<{ end: number; duration?: number; label: string }> = ({ end, duration = 2000, label }) => {
  const [count, setCount] = useState(0);
  const countRef = useRef<HTMLDivElement>(null);
  const [hasAnimated, setHasAnimated] = useState(false);

  useEffect(() => {
    setHasAnimated(false);
  }, [end]);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && !hasAnimated) {
          let start = 0;
          const increment = end / (duration / 16);
          const timer = setInterval(() => {
            start += increment;
            if (start >= end) {
              setCount(end);
              clearInterval(timer);
            } else {
              setCount(Math.ceil(start));
            }
          }, 16);
          setHasAnimated(true);
        }
      },
      { threshold: 0.5 }
    );

    if (countRef.current) observer.observe(countRef.current);
    return () => observer.disconnect();
  }, [end, duration, hasAnimated]);

  return (
    <div ref={countRef} className="bg-white dark:bg-dark-card p-6 rounded-lg shadow-sm text-center border-b-4 border-leaf hover:-translate-y-1 transition-transform duration-300">
      <h3 className="text-4xl font-bold text-gray-800 dark:text-white mb-2">{count}+</h3>
      <p className="text-gray-500 dark:text-gray-400 font-medium uppercase tracking-wide text-sm">{label}</p>
    </div>
  );
};

