  const handleProfilePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => { 
    if (e.target.files && e.target.files[0]) {
      setEditProfileForm({...editProfileForm, photo: e.target.files[0]});
      setEditPhotoPreview(URL.createObjectURL(e.target.files[0]));
    }
  };

  const handleProfileUpdate = async (e: React.FormEvent) => { 
    e.preventDefault();
    if (!user) return;
    setIsUpdatingProfile(true);
    const success = await updateUserProfile(user.email, editProfileForm.designation, editProfileForm.company, editProfileForm.currentAddress, editProfileForm.bloodGroup, editProfileForm.photo, editProfileForm.dob, editProfileForm.isMentor);
