      toast.success("Profile Updated!");
      setIsEditingProfile(false);
      const updatedUser = { 
        ...user, 
        data: { 
          ...user.data!, 
          ...editProfileForm, 
          photoUrl: editPhotoPreview || user.data!.photoUrl 
