      };
      setUser(updatedUser);
      localStorage.setItem('ssaa_current_user', JSON.stringify(updatedUser));
    } else {
      toast.error("Failed to update profile");
    }
    setIsUpdatingProfile(false);
  };

  const handleDonationStatus = async (id: string, newStatus: string) => {
    if (confirm(`Mark this donation as ${newStatus}?`)) {
      setDonations(prev => prev.map(d => d.id === id ? { ...d, status: newStatus as any } : d));
      const success = await updateDonationStatus(id, newStatus);
      if (success) toast.success(`Donation ${newStatus}`);
      else { toast.error("Failed"); loadDonations(); }
    }
  };

  const handleRSVP = async (event: Event) => {
    if (!user) return;
    if (event.price > 0) {
      // Paid event
      openModal('eventPayment', event);
    } else {
