              <div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Current Designation</label><input required type="text" value={editProfileForm.designation} onChange={e => setEditProfileForm({...editProfileForm, designation: e.target.value})} className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white" /></div>
              <div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Company/Organization</label><input type="text" value={editProfileForm.company} onChange={e => setEditProfileForm({...editProfileForm, company: e.target.value})} className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white" /></div>
              <div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Blood Group</label><select value={editProfileForm.bloodGroup} onChange={e => setEditProfileForm({...editProfileForm, bloodGroup: e.target.value})} className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white"><option value="">Select...</option>{['A+','A-','B+','B-','AB+','AB-','O+','O-'].map(b=><option key={b} value={b}>{b}</option>)}</select></div>
              <div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Date of Birth</label><input type="date" value={editProfileForm.dob} onChange={e => setEditProfileForm({...editProfileForm, dob: e.target.value})} className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white" /></div>
              <div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Current Address</label><textarea required rows={2} value={editProfileForm.currentAddress} onChange={e => setEditProfileForm({...editProfileForm, currentAddress: e.target.value})} className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white" /></div>
              <div className="flex justify-end pt-2"><button type="button" onClick={() => setIsEditingProfile(false)} className="mr-3 px-4 py-2 text-gray-700 dark:text-gray-300 font-medium hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors">Cancel</button><button type="submit" disabled={isUpdatingProfile} className="px-6 py-2 bg-leaf text-white font-medium rounded-lg hover:bg-leaf-dark flex items-center shadow-sm disabled:opacity-70">{isUpdatingProfile ? <RefreshCw className="animate-spin mr-2 w-4 h-4" /> : null} Save Changes</button></div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

