import { MOCK_BLOG_POSTS, MOCK_GALLERY, APP_LOGO_URL } from '../constants';
import { BlogPost, GalleryItem, User, Event, RSVP } from '../types';
import { getBlogPosts, submitDonation, rsvpToEvent } from '../services/googleSheetService';

const formatDate = (dateString: string) => {
  if (!dateString) return '';
  const date = new Date(dateString);
  if (isNaN(date.getTime())) return dateString;
  return new Intl.DateTimeFormat('en-US', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: true
  }).format(date);
};

const GlobalModals: React.FC = () => {
  const { activeModal, closeModal, openModal, modalData } = useModal();
  const [posts, setPosts] = useState<BlogPost[]>(MOCK_BLOG_POSTS);

  // Refs for Tickets/Cards
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Donation Form State
  const [donationForm, setDonationForm] = useState({ name: '', email: '', amount: '', method: 'Bkash', account: '', trxId: '' });
  const [isDonating, setIsDonating] = useState(false);

  // Event Payment State
  const [eventPaymentForm, setEventPaymentForm] = useState({ trxId: '', method: 'Bkash', account: '' });
  const [isProcessingPayment, setIsProcessingPayment] = useState(false);

  // Fetch real posts when a relevant modal opens
  useEffect(() => {
    if (activeModal === 'activities' || activeModal === 'success' || activeModal === 'gallery') {
      getBlogPosts().then(fetchedPosts => {
        if (fetchedPosts.length > 0) setPosts(fetchedPosts);
      });
    }
  }, [activeModal]);

  // ID Card Logic
  useEffect(() => {
    if (activeModal === 'idCard' && modalData && canvasRef.current) {
       drawIdCard(modalData as User);
    }
  }, [activeModal, modalData]);

  const handleOpenPost = (post: BlogPost) => {
    openModal('post', post);
  };

  const handleDonationSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsDonating(true);
    const success = await submitDonation(donationForm.name, donationForm.email, donationForm.amount, donationForm.method, donationForm.account, donationForm.trxId);
    if (success) {
      toast.success("Donation details submitted! We will verify shortly.");
      setDonationForm({ name: '', email: '', amount: '', method: 'Bkash', account: '', trxId: '' });
      closeModal();
    } else {
      toast.error("Failed to submit donation.");
    }
    setIsDonating(false);
  };

  const handleEventPaymentSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const event = modalData as Event;
    const user = JSON.parse(localStorage.getItem('ssaa_current_user') || '{}') as User;

    if(!user || !event) return;

    setIsProcessingPayment(true);
    const success = await rsvpToEvent(event.id, user.email, 'Pending Payment', eventPaymentForm.trxId);

    if(success) {
      toast.success("Payment info submitted! Your ticket will be confirmed after verification.");
      setEventPaymentForm({ trxId: '', method: 'Bkash', account: '' });
      closeModal();
      // Optionally trigger a refresh in Dashboard
      window.location.reload(); 
    } else {
      toast.error("Failed to submit payment.");
    }
    setIsProcessingPayment(false);
  };

  const drawIdCard = (user: User) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Load assets
    const logoImg = new Image();
    logoImg.src = APP_LOGO_URL;
    logoImg.crossOrigin = "Anonymous";

    const profileImg = new Image();
    profileImg.src = user.data?.photoUrl || `https://ui-avatars.com/api/?background=random&color=fff&name=${encodeURIComponent(user.name)}`;
    profileImg.crossOrigin = "Anonymous";

    const draw = () => {
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(0, 0, 600, 380);

      ctx.fillStyle = "#5D4037"; // Soil Color
      ctx.fillRect(0, 0, 600, 100);

      ctx.textAlign = "center";
      ctx.fillStyle = "#ffffff";

      ctx.font = "bold 24px Arial";
      ctx.fillText("Soil Science Alumni Association", 270, 45);

      ctx.font = "15px Arial";
      ctx.fillText("Government Shaheed Suhrawardy College", 270, 70);

      ctx.save();
      ctx.beginPath();
      ctx.arc(530, 50, 40, 0, Math.PI * 2, true);
      ctx.fillStyle = "#ffffff";
      ctx.fill();
      ctx.closePath();

      try {
        ctx.drawImage(logoImg, 495, 15, 70, 70); 
      } catch(e) {
        ctx.fillStyle = "#ccc";
        ctx.fill();
        ctx.fillStyle = "#5D4037";
        ctx.font = "bold 20px Arial";
        ctx.fillText("SSAA", 530, 55);
      }
      ctx.restore();

      const photoX = 100;
      const photoY = 220;
      const photoRadius = 75;

      ctx.save();
      ctx.beginPath();
      ctx.arc(photoX, photoY, photoRadius, 0, Math.PI * 2, true);
      ctx.closePath();
      ctx.clip();

      ctx.fillStyle = "#f3f4f6";
      ctx.fillRect(photoX - photoRadius, photoY - photoRadius, photoRadius * 2, photoRadius * 2);

      try {
        ctx.drawImage(profileImg, photoX - photoRadius, photoY - photoRadius, photoRadius * 2, photoRadius * 2);
      } catch (e) {
        ctx.fillStyle = "#ccc";
        ctx.fillRect(photoX - photoRadius, photoY - photoRadius, photoRadius * 2, photoRadius * 2);
      }
      ctx.restore();

      ctx.beginPath();
      ctx.arc(photoX, photoY, photoRadius, 0, Math.PI * 2, true);
      ctx.strokeStyle = "#43A047"; 
      ctx.lineWidth = 6;
      ctx.stroke();

      ctx.textAlign = "left";
      const textStartX = 210;
      let textY = 160;

      ctx.fillStyle = "#1f2937";
      ctx.font = "bold 28px Arial";
      ctx.fillText(user.name, textStartX, textY);

      textY += 15;
      ctx.beginPath();
      ctx.moveTo(textStartX, textY);
      ctx.lineTo(550, textY);
      ctx.strokeStyle = "#e5e7eb";
      ctx.lineWidth = 2;
      ctx.stroke();

      textY += 35;
      const labelOffset = 0;
      const valueOffset = 130;
      const rowGap = 35;

      const drawRow = (label: string, value: string, color: string = "#374151") => {
        ctx.font = "bold 14px Arial";
        ctx.fillStyle = "#8D6E63";
        ctx.fillText(label, textStartX + labelOffset, textY);

        ctx.font = "bold 16px Arial";
        ctx.fillStyle = color;
        ctx.fillText(value, textStartX + valueOffset, textY);

        textY += rowGap;
      };

      drawRow("Membership ID:", user.data?.password || "N/A");
      drawRow("Session:", user.data?.session || "N/A");
      drawRow("Batch:", user.data?.batch || "N/A");
      drawRow("Blood:", user.data?.bloodGroup || "N/A", "#dc2626");

      ctx.fillStyle = "#43A047";
      ctx.fillRect(0, 360, 600, 20);

      ctx.textAlign = "center";
      ctx.font = "12px math ";
      ctx.fillStyle = "#fff";
      ctx.fillText("gsscsoilalumni@gmail.com  |  Estd. 2020", 300, 374);
    };

    let loaded = 0;
    const checkLoad = () => {
      loaded++;
      if (loaded >= 2) draw();
    };
    logoImg.onload = checkLoad;
    logoImg.onerror = checkLoad;
    profileImg.onload = checkLoad;
    profileImg.onerror = checkLoad;

    if (logoImg.complete && profileImg.complete) draw();
    setTimeout(draw, 500);
  };

  const downloadIdCard = () => {
    if (!canvasRef.current) return;
    const link = document.createElement('a');
