export const rsvpToEvent = async (eventId: string | number, userEmail: string, status: 'Going' | 'Pending Payment', trxId?: string): Promise<boolean> => {
  // Mock Implementation
  const allRSVPs = localStorage.getItem(RSVP_KEY);
  let parsed: RSVP[] = allRSVPs ? JSON.parse(allRSVPs) : [];

  // Remove existing
  parsed = parsed.filter(r => !(r.eventId === eventId && r.userEmail === userEmail));

  const ticketCode = status === 'Going' ? `TKT-${eventId}-${Math.floor(1000 + Math.random() * 9000)}` : undefined;

  parsed.push({
    eventId,
    userEmail,
    status,
    trxId,
