                         ) : (
                           <span className={`px-2 py-1 rounded-full text-xs font-bold ${member.status === 'Approved' ? 'bg-green-100 text-green-700' : member.status === 'Rejected' ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'}`}>{member.status}</span>
                         )}
                       </td>
                     </tr>
                   ))}
                 </tbody>
               </table>
