              </div>
              <div className="flex gap-2 w-full md:w-auto">
                <select value={bloodFilter} onChange={(e) => setBloodFilter(e.target.value)} className="w-full md:w-40 px-4 py-3 border rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white dark:bg-gray-800 text-gray-900 dark:text-white border-gray-200 dark:border-gray-600">
