                 {user.role === 'admin' && <button onClick={loadDonations} className="text-sm text-gray-500 dark:text-gray-400 flex items-center bg-gray-100 dark:bg-gray-700 px-3 py-2 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-600"><RefreshCw size={14} className="mr-1" /> Refresh</button>}
