                  <thead><tr className="bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 text-sm uppercase tracking-wider"><th className="px-6 py-4 font-semibold">Date</th><th className="px-6 py-4 font-semibold">Donor</th><th className="px-6 py-4 font-semibold">Amount</th><th className="px-6 py-4 font-semibold">Details</th><th className="px-6 py-4 font-semibold">Status</th>{user.role === 'admin' && <th className="px-6 py-4 font-semibold text-right">Action</th>}</tr></thead>
                  <tbody className="divide-y divide-gray-100 dark:divide-gray-700 text-gray-900 dark:text-gray-200">
                    {visibleDonations.length > 0 ? visibleDonations.map((d) => (
                      <tr key={d.id} className="hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors">
