                        <td className="px-6 py-4"><p className="font-semibold">{d.donorName}</p><p className="text-xs text-gray-500 dark:text-gray-400">{d.donorEmail}</p></td>
                        <td className="px-6 py-4 font-bold text-soil dark:text-soil-light">{d.amount} BDT</td>
                        <td className="px-6 py-4 text-sm text-gray-600 dark:text-gray-400"><p><span className="font-medium">Via:</span> {d.method}</p><p><span className="font-medium">Acc:</span> {d.accountNumber}</p><p><span className="font-medium">TrxID:</span> {d.trxId}</p></td>
                        <td className="px-6 py-4"><span className={`px-2 py-1 rounded-full text-xs font-bold ${d.status === 'Approved' ? 'bg-green-100 text-green-700' : d.status === 'Rejected' ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'}`}>{d.status}</span></td>
                        {user.role === 'admin' && (<td className="px-6 py-4 text-right">{d.status === 'Pending' && (<div className="flex justify-end gap-2"><button onClick={() => handleDonationStatus(d.id, 'Approved')} className="text-green-600 hover:bg-green-50 p-1 rounded" title="Approve"><Check size={18} /></button><button onClick={() => handleDonationStatus(d.id, 'Rejected')} className="text-red-600 hover:bg-red-50 p-1 rounded" title="Reject"><XIcon size={18} /></button></div>)}</td>)}
                      </tr>
                    )) : (<tr><td colSpan={user.role === 'admin' ? 6 : 5} className="px-6 py-8 text-center text-gray-500 dark:text-gray-400">No donation records found.</td></tr>)}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {/* CAREER - Dark Mode */}
        {activeTab === 'career' && (
          <div className="space-y-8">
