              {careerPosts.length > 0 ? careerPosts.map(post => (
                <div key={post.id} className="bg-white dark:bg-dark-card p-6 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 hover:shadow-md transition-all">
                  <div className="flex justify-between items-start"><div><h4 className="text-xl font-bold text-gray-900 dark:text-white line-clamp-2">{post.title}</h4><p className="text-soil dark:text-soil-light font-medium text-sm mt-1">{post.category}</p></div><span className="text-xs bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 px-2 py-1 rounded whitespace-nowrap">{formatDate(post.date)}</span></div>
                  <p className="text-gray-600 dark:text-gray-300 text-sm mt-3 line-clamp-3">{post.excerpt}</p>
                  <div className="mt-4 pt-4 border-t border-gray-50 dark:border-gray-700 flex justify-end"><span className="text-xs text-gray-400 italic">Check Home page for full details</span></div>
                </div>
              )) : <p className="col-span-2 text-center text-gray-500 dark:text-gray-400 py-10">No job circulars posted yet.</p>}
