</div></div></div><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Short Excerpt</label><textarea required rows={2} value={postForm.excerpt} onChange={e => setPostForm({...postForm, excerpt: e.target.value})} className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-soil focus:border-transparent outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white" /></div><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Full Content</label><textarea rows={6} value={postForm.content} onChange={e => setPostForm({...postForm, content: e.target.value})} className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-soil focus:border-transparent outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white" /></div><div className="pt-4 flex justify-end"><button type="submit" disabled={isPosting} className="bg-leaf hover:bg-leaf-dark text-white px-8 py-3 rounded-full font-bold shadow-md hover:shadow-lg transition-all flex items-center">{isPosting ? <RefreshCw className="animate-spin mr-2" /> : <Send className="mr-2" />}{isEditingPost ? 'Update Post' : 'Publish Post'}</button></div></form></div>
              <div className="p-6 border-t border-gray-100 dark:border-gray-700"><div className="flex justify-between items-center mb-4"><h3 className="text-lg font-bold text-gray-900 dark:text-white">Manage Posts</h3><button onClick={loadPosts} className="text-sm text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200 flex items-center"><RefreshCw size={14} className="mr-1" /> Refresh List</button></div><div className="overflow-x-auto"><table className="w-full text-left border-collapse"><thead><tr className="bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 text-sm uppercase tracking-wider"><th className="px-6 py-4 font-semibold">Title</th><th className="px-6 py-4 font-semibold">Category</th><th className="px-6 py-4 font-semibold text-right">Actions</th></tr></thead><tbody className="divide-y divide-gray-100 dark:divide-gray-700 text-gray-900 dark:text-gray-200">{posts.length > 0 ? posts.map((post) => (<tr key={post.id} className="hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors"><td className="px-6 py-4 font-medium">{post.title}</td><td className="px-6 py-4"><span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${post.category === 'Career' ? 'bg-purple-100 text-purple-800' : post.category === 'Activity' ? 'bg-blue-100 text-blue-800' : 'bg-gray-100 dark:bg-gray-700 text-gray-800 dark:text-gray-200'}`}>{post.category}</span></td><td className="px-6 py-4 text-right"><button onClick={() => handleEditClick(post)} className="text-soil hover:text-soil-dark dark:text-soil-light font-medium text-sm flex items-center justify-end"><Edit size={16} className="mr-1" /> Edit</button></td></tr>)) : <tr><td colSpan={3} className="px-6 py-8 text-center text-gray-500 dark:text-gray-400">No posts found.</td></tr>}</tbody></table></div></div>
          </div>
