              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Profile Picture</label>
                <div className="flex items-center gap-4">
                  <div className="w-16 h-16 rounded-full border border-gray-200 dark:border-gray-600 overflow-hidden bg-gray-100 dark:bg-gray-700">{editPhotoPreview ? (<img src={editPhotoPreview} alt="Preview" className="w-full h-full object-cover" />) : (<div className="w-full h-full flex items-center justify-center bg-soil text-white text-xl font-bold">P</div>)}</div>
                  <label className="cursor-pointer bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-300 px-4 py-2 rounded-lg text-sm font-medium hover:bg-gray-50 dark:hover:bg-gray-600 transition-colors">Change Photo<input type="file" className="hidden" accept="image/*" onChange={handleProfilePhotoChange} /></label>
                </div>
              </div>

              {/* MENTOR TOGGLE */}
              <div className="bg-indigo-50 dark:bg-indigo-900/30 p-4 rounded-lg border border-indigo-100 dark:border-indigo-800 flex items-start gap-3">
                 <input 
                   type="checkbox" 
                   id="isMentor"
                   checked={editProfileForm.isMentor}
                   onChange={e => setEditProfileForm({...editProfileForm, isMentor: e.target.checked})}
                   className="mt-1 w-4 h-4 text-indigo-600 rounded focus:ring-indigo-500"
                 />
                 <div>
                    <label htmlFor="isMentor" className="block text-sm font-bold text-indigo-900 dark:text-indigo-200 cursor-pointer">Available for Mentorship</label>
                    <p className="text-xs text-indigo-700 dark:text-indigo-400 mt-1">Check this if you are willing to guide junior alumni or students with career advice.</p>
                 </div>
              </div>

              <div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Current Designation</label><input required type="text" value={editProfileForm.designation} onChange={e => setEditProfileForm({...editProfileForm, designation: e.target.value})} className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white" /></div>
              <div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Company/Organization</label><input type="text" value={editProfileForm.company} onChange={e => setEditProfileForm({...editProfileForm, company: e.target.value})} className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white" /></div>
              <div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Blood Group</label><select value={editProfileForm.bloodGroup} onChange={e => setEditProfileForm({...editProfileForm, bloodGroup: e.target.value})} className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white"><option value="">Select...</option>{['A+','A-','B+','B-','AB+','AB-','O+','O-'].map(b=><option key={b} value={b}>{b}</option>)}</select></div>
              <div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Date of Birth</label><input type="date" value={editProfileForm.dob} onChange={e => setEditProfileForm({...editProfileForm, dob: e.target.value})} className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white" /></div>
              <div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Current Address</label><textarea required rows={2} value={editProfileForm.currentAddress} onChange={e => setEditProfileForm({...editProfileForm, currentAddress: e.target.value})} className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white" /></div>
              <div className="flex justify-end pt-2"><button type="button" onClick={() => setIsEditingProfile(false)} className="mr-3 px-4 py-2 text-gray-700 dark:text-gray-300 font-medium hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors">Cancel</button><button type="submit" disabled={isUpdatingProfile} className="px-6 py-2 bg-leaf text-white font-medium rounded-lg hover:bg-leaf-dark flex items-center shadow-sm disabled:opacity-70">{isUpdatingProfile ? <RefreshCw className="animate-spin mr-2 w-4 h-4" /> : null} Save Changes</button></div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  LogOut, User as UserIcon, MessageSquare, Users, Briefcase, FileText, 
  Send, Plus, Check, X as XIcon, Search, Loader2, Menu, LayoutDashboard, Heart, RefreshCw, PenTool, Upload, Edit, ExternalLink, Headphones,
  MessageCircle, Mail, Phone, MapPin, Calendar, Grid, Award, DollarSign, ChevronLeft, ShieldAlert, CreditCard, Gift, Megaphone, Star, CalendarDays, Ticket, Save
} from 'lucide-react';
import toast from 'react-hot-toast';
import { User, ChatMessage, AlumniRegistrationData, JobPost, BlogPost, Donation, Event, RSVP } from '../types';
import { 
  getAllMembers, updateMemberStatus, sendChatMessage, getBatchMessages, 
  createBlogPost, updateBlogPost, getBlogPosts, createJobPost, getJobPosts, updateUserProfile, getDonations, updateDonationStatus,
  getAdminNotice, updateAdminNotice, getEvents, getRSVPs, rsvpToEvent, createEvent, updateEvent
} from '../services/googleSheetService';
import { APP_LOGO_URL } from '../constants';
import { useModal } from '../context/ModalContext';

// Helper interface for Admin Messenger
interface ConversationSummary {
  email: string;
  name: string;
  photoUrl: string;
  lastMessage: string;
  timestamp: string;
  unreadCount: number;
}

const formatDate = (dateString: string) => {
  if (!dateString) return '';
  const date = new Date(dateString);
  if (isNaN(date.getTime())) return dateString;
  return new Intl.DateTimeFormat('en-US', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: true
  }).format(date);
};

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const { openModal } = useModal();

  const [user, setUser] = useState<User | null>(null);
  const [allMembers, setAllMembers] = useState<AlumniRegistrationData[]>([]);
  const [activeTab, setActiveTab] = useState<'profile' | 'events' | 'admin' | 'chat' | 'post' | 'career' | 'search' | 'donation'>('profile');
  const [isSidebarOpen, setSidebarOpen] = useState(window.innerWidth > 768);

  // Profile Edit State
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editProfileForm, setEditProfileForm] = useState({ designation: '', company: '', currentAddress: '', bloodGroup: '', photo: null as File | null, dob: '', isMentor: false });
  const [editPhotoPreview, setEditPhotoPreview] = useState<string | null>(null);
  const [isUpdatingProfile, setIsUpdatingProfile] = useState(false);

  // Chat State
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [isSendingMsg, setIsSendingMsg] = useState(false);
  const [isRefreshingChat, setIsRefreshingChat] = useState(false);

  // Member Chat State
  const [memberChatMode, setMemberChatMode] = useState<'BATCH' | 'ADMIN'>('BATCH');

  // Admin Chat State
  const [adminChatSession, setAdminChatSession] = useState<string>(''); 
  const [adminChatMode, setAdminChatMode] = useState<'BATCH' | 'DM'>('BATCH');
  const [adminSelectedMemberEmail, setAdminSelectedMemberEmail] = useState<string>('');
  const [conversations, setConversations] = useState<ConversationSummary[]>([]); // New: For Messenger Sidebar

  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatIntervalRef = useRef<number | null>(null);

  // Post State
  const [posts, setPosts] = useState<BlogPost[]>([]);
  const [isEditingPost, setIsEditingPost] = useState<string | null>(null);
  const [postForm, setPostForm] = useState({ title: '', category: 'Activity', excerpt: '', content: '', image: null as File | null });
  const [postImagePreview, setPostImagePreview] = useState<string | null>(null);
  const [isPosting, setIsPosting] = useState(false);

  // Job State
  const [jobs, setJobs] = useState<JobPost[]>([]);
  const [jobForm, setJobForm] = useState({ title: '', company: '', deadline: '', link: '' });

  // Event State
  const [events, setEvents] = useState<Event[]>([]);
  const [userRSVPs, setUserRSVPs] = useState<RSVP[]>([]);
  const [isSubmittingRSVP, setIsSubmittingRSVP] = useState(false);
  const [isCreatingEvent, setIsCreatingEvent] = useState(false);
  const [eventForm, setEventForm] = useState<Partial<Event> & { imageFile?: File | null }>({ title: '', description: '', location: '', price: 0, date: '', time: '', registrationDeadline: '', imageFile: null });
  const [eventImagePreview, setEventImagePreview] = useState<string | null>(null);
  const [isSubmittingEvent, setIsSubmittingEvent] = useState(false);
  const [editingEventId, setEditingEventId] = useState<string | number | null>(null);

  // Search State
  const [searchQuery, setSearchQuery] = useState('');
  const [bloodFilter, setBloodFilter] = useState('');
  const [showMentorsOnly, setShowMentorsOnly] = useState(false);

  // Donation State
  const [donations, setDonations] = useState<Donation[]>([]);

  // Admin Notice State
  const [adminNotice, setAdminNotice] = useState('');
  const [isEditingNotice, setIsEditingNotice] = useState(false);
  const [newNoticeText, setNewNoticeText] = useState('');

  const topRef = useRef<HTMLDivElement>(null);

  const uniqueSessions = Array.from(new Set(allMembers.map(m => m.session).filter(Boolean))).sort();

  useEffect(() => {
    const checkAuth = async () => {
      const storedUser = localStorage.getItem('ssaa_current_user');
      if (!storedUser) { navigate('/login'); return; }
      const parsedUser: User = JSON.parse(storedUser);
      setUser(parsedUser);
      getAllMembers().then(setAllMembers);
      loadPosts();
      loadNotice();
    };
    checkAuth();
    return () => stopChatPolling();
  }, [navigate]);

  useEffect(() => {
    const handleResize = () => setSidebarOpen(window.innerWidth > 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    if (activeTab === 'chat') startChatPolling();
    else stopChatPolling();
    return () => stopChatPolling();
  }, [activeTab, adminChatSession, user, adminChatMode, memberChatMode, adminSelectedMemberEmail]);

  useEffect(() => {
    if (activeTab === 'post' || activeTab === 'career') loadPosts();
    if (activeTab === 'career') loadJobs();
    if (activeTab === 'donation') loadDonations();
    if (activeTab === 'events') loadEvents();
  }, [activeTab]);

  const loadPosts = async () => { const fetched = await getBlogPosts(); setPosts(fetched); };
  const loadJobs = async () => { const data = await getJobPosts(); setJobs(data); };
  const loadDonations = async () => { const data = await getDonations(); setDonations(data); };
  const loadNotice = async () => { const notice = await getAdminNotice(); setAdminNotice(notice); setNewNoticeText(notice); };
  const loadEvents = async () => {
    const ev = await getEvents();
    setEvents(ev);
    if (user) {
      const rsvps = await getRSVPs(user.email);
      setUserRSVPs(rsvps);
    }
  };

  const handleUpdateNotice = async () => {
    await updateAdminNotice(newNoticeText);
    setAdminNotice(newNoticeText);
    setIsEditingNotice(false);
    toast.success("Broadcast updated!");
  };

  const startChatPolling = () => { stopChatPolling(); fetchMessages(); chatIntervalRef.current = window.setInterval(fetchMessages, 5000); };
  const stopChatPolling = () => { if (chatIntervalRef.current) { clearInterval(chatIntervalRef.current); chatIntervalRef.current = null; } };

  const getChatSessionID = () => { 
    if (!user) return ''; 
    if (user.role === 'admin') { 
      if (adminChatMode === 'DM') {
        return 'ALL_SUPPORT'; 
      }
      return adminChatSession || ''; 
    } else { 
      // Member Logic
      if (memberChatMode === 'ADMIN') {
        return `SUPPORT_${user.email}`;
      }
      return user.data?.session || ''; 
    } 
  };

  const fetchMessages = async () => { 
    if (!user) return;
    setIsRefreshingChat(true);

    const sessionParam = getChatSessionID(); 
    let batchParam = '';
    if (user.role === 'admin') {
      batchParam = 'ADMIN_VIEW';
    } else if (memberChatMode === 'ADMIN') {
      batchParam = 'SUPPORT';
    } else {
      batchParam = user.data?.batch || '';
    }

    if (sessionParam) {
      const msgs = await getBatchMessages(sessionParam, batchParam);

      if (user.role === 'admin' && adminChatMode === 'DM') {
        // --- MESSENGER LOGIC START (ADMIN) ---
        const convMap: Record<string, ConversationSummary> = {};

        msgs.forEach(msg => {
          if (msg.session && msg.session.startsWith('SUPPORT_')) {
            const userEmail = msg.session.replace('SUPPORT_', '');
            const member = allMembers.find(m => m.email === userEmail);
            const name = member ? member.name : userEmail;
            const photo = member ? (member.photoUrl || '') : '';

            if (!convMap[userEmail]) {
              convMap[userEmail] = {
                email: userEmail,
                name: name,
                photoUrl: photo,
                lastMessage: '',
                timestamp: '',
                unreadCount: 0
              };
            }
            convMap[userEmail].lastMessage = msg.message;
            convMap[userEmail].timestamp = msg.timestamp;
          }
        });

        const convArray = Object.values(convMap);
        convArray.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
        setConversations(convArray);

        if (adminSelectedMemberEmail) {
          const targetSession = `SUPPORT_${adminSelectedMemberEmail}`;
          const currentChat = msgs.filter(m => m.session === targetSession);
          setChatMessages(currentChat.slice(-50).map(m => ({ ...m, isMe: m.senderEmail === user.email })));
        } else {
          setChatMessages([]);
        }
        // --- MESSENGER LOGIC END ---

      } else {
        // Normal Batch Chat Logic (Admin Batch View OR Member View)
        if (msgs) {
           setChatMessages(msgs.map(m => ({ ...m, isMe: m.senderEmail === user.email })));
        }
      }
    }
    setIsRefreshingChat(false);
  };

  const handleLogout = () => { localStorage.removeItem('ssaa_current_user'); window.dispatchEvent(new Event('auth-change')); navigate('/login'); };

  const handleSendMessage = async (e: React.FormEvent) => { 
    e.preventDefault();
    if (!newMessage.trim() || !user) return;
    setIsSendingMsg(true);

    let session = '';
    let batch = '';

    if (user.role === 'admin') {
      if (adminChatMode === 'DM') {
        if (!adminSelectedMemberEmail) { toast.error("Select a conversation"); setIsSendingMsg(false); return; }
        session = `SUPPORT_${adminSelectedMemberEmail}`;
        batch = 'SUPPORT'; // Reply batch context
      } else {
        session = adminChatSession;
        batch = 'ADMIN_REPLY'; // Or just 'ALL'
      }
    } else {
      // Member
      if (memberChatMode === 'ADMIN') {
        session = `SUPPORT_${user.email}`;
        batch = 'SUPPORT';
      } else {
        session = user.data?.session || '';
        batch = user.data?.batch || '';
      }
    }

    if (!session) { toast.error("Select a chat room"); setIsSendingMsg(false); return; }

    const success = await sendChatMessage(session, batch, user.name, user.email, user.data?.photoUrl || '', newMessage);
    if (success) { setNewMessage(''); fetchMessages(); } else { toast.error("Failed to send"); }
    setIsSendingMsg(false);
  };

  const handleStatusUpdate = async (email: string, newStatus: string) => { if (confirm(`Change status to ${newStatus}?`)) { setAllMembers(prev => prev.map(m => m.email === email ? { ...m, status: newStatus as any } : m)); await updateMemberStatus(email, newStatus); } };
  const handleSubmitJob = async (e: React.FormEvent) => { e.preventDefault(); const success = await createJobPost(jobForm.title, jobForm.company, jobForm.deadline, jobForm.link); if (success) { toast.success("Posted!"); setJobForm({ title: '', company: '', deadline: '', link: '' }); loadJobs(); } };

  const handlePostImageChange = (e: React.ChangeEvent<HTMLInputElement>) => { 
    if (e.target.files && e.target.files[0]) {
      setPostForm({...postForm, image: e.target.files[0]});
      setPostImagePreview(URL.createObjectURL(e.target.files[0]));
    }
  };

  const handleEditClick = (post: BlogPost) => { 
    setIsEditingPost(post.id.toString());
    setPostForm({ title: post.title, category: post.category, excerpt: post.excerpt, content: post.content || '', image: null });
    setPostImagePreview(post.imageUrl);
  };

  const handleCancelEdit = () => { 
    setIsEditingPost(null);
    setPostForm({ title: '', category: 'Activity', excerpt: '', content: '', image: null });
    setPostImagePreview(null);
  };

  const handleSubmitPost = async (e: React.FormEvent) => { 
    e.preventDefault();
    setIsPosting(true);
    let success = false;
    if (isEditingPost) {
       success = await updateBlogPost(isEditingPost, postForm.title, postForm.category, postForm.excerpt, postForm.content, postForm.image, postImagePreview || '');
    } else {
       success = await createBlogPost(postForm.title, postForm.category, postForm.excerpt, postForm.content, postForm.image);
    }
    if (success) { toast.success(isEditingPost ? "Updated!" : "Created!"); handleCancelEdit(); loadPosts(); } else { toast.error("Failed"); }
    setIsPosting(false);
  };

  const handleOpenEditProfile = () => { 
    if (user?.data) {
      setEditProfileForm({
        designation: user.data.designation,
        company: user.data.company || '',
        currentAddress: user.data.currentAddress,
        bloodGroup: user.data.bloodGroup || '',
        photo: null,
        dob: user.data.dob || '',
        isMentor: user.data.isMentor || false
      });
      setEditPhotoPreview(user.data.photoUrl || null);
      setIsEditingProfile(true);
    }
  };

  const handleProfilePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => { 
    if (e.target.files && e.target.files[0]) {
      setEditProfileForm({...editProfileForm, photo: e.target.files[0]});
      setEditPhotoPreview(URL.createObjectURL(e.target.files[0]));
    }
  };

  const handleProfileUpdate = async (e: React.FormEvent) => { 
    e.preventDefault();
    if (!user) return;
    setIsUpdatingProfile(true);
    const success = await updateUserProfile(user.email, editProfileForm.designation, editProfileForm.company, editProfileForm.currentAddress, editProfileForm.bloodGroup, editProfileForm.photo, editProfileForm.dob, editProfileForm.isMentor);
    if (success) {
      toast.success("Profile Updated!");
      setIsEditingProfile(false);
      const updatedUser = { 
        ...user, 
        data: { 
          ...user.data!, 
          ...editProfileForm, 
          photoUrl: editPhotoPreview || user.data!.photoUrl 
        } 
      };
      setUser(updatedUser);
      localStorage.setItem('ssaa_current_user', JSON.stringify(updatedUser));
    } else {
      toast.error("Failed to update profile");
    }
    setIsUpdatingProfile(false);
  };

  const handleDonationStatus = async (id: string, newStatus: string) => {
    if (confirm(`Mark this donation as ${newStatus}?`)) {
      setDonations(prev => prev.map(d => d.id === id ? { ...d, status: newStatus as any } : d));
      const success = await updateDonationStatus(id, newStatus);
      if (success) toast.success(`Donation ${newStatus}`);
      else { toast.error("Failed"); loadDonations(); }
    }
  };

  const handleRSVP = async (event: Event) => {
    if (!user) return;
    if (event.price > 0) {
      // Paid event
      openModal('eventPayment', event);
    } else {
      // Free event
      if (confirm(`Confirm your attendance for ${event.title}?`)) {
        setIsSubmittingRSVP(true);
        const success = await rsvpToEvent(event.id, user.email, 'Going');
        if (success) {
          toast.success("RSVP Confirmed! You are going.");
          loadEvents();
        }
        setIsSubmittingRSVP(false);
      }
    }
  };

  const handleEventImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setEventForm({...eventForm, imageFile: e.target.files[0]});
      setEventImagePreview(URL.createObjectURL(e.target.files[0]));
    }
  };

  const handleCreateEventSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmittingEvent(true);

    // Basic validation
    if(!eventForm.title || !eventForm.date) {
      toast.error("Title and Date are required");
      setIsSubmittingEvent(false);
      return;
    }

    const eventData: any = {
      title: eventForm.title,
      description: eventForm.description,
      location: eventForm.location,
      price: Number(eventForm.price) || 0,
      date: eventForm.date,
      time: eventForm.time,
      registrationDeadline: eventForm.registrationDeadline,
      imageUrl: eventImagePreview || ""
    };

    let success = false;
    if (editingEventId) {
      success = await updateEvent({ ...eventData, id: editingEventId }, eventForm.imageFile || null);
    } else {
      success = await createEvent(eventData, eventForm.imageFile || null);
    }

    if (success) {
      toast.success(editingEventId ? "Event Updated!" : "Event Created!");
      setIsCreatingEvent(false);
      setEditingEventId(null);
      setEventForm({ title: '', description: '', location: '', price: 0, date: '', time: '', registrationDeadline: '', imageFile: null });
      setEventImagePreview(null);
      loadEvents();
    } else {
      toast.error("Failed to save event");
    }
    setIsSubmittingEvent(false);
  };

  const handleEditEvent = (event: Event) => {
    setEditingEventId(event.id);
    setEventForm({
      title: event.title,
      description: event.description,
      location: event.location,
      price: event.price,
      date: event.date,
      time: event.time,
      registrationDeadline: event.registrationDeadline,
      imageFile: null
    });
    setEventImagePreview(event.imageUrl);
    setIsCreatingEvent(true);
  };

  const getBirthdayMembers = () => {
    const today = new Date();
    const currentMonth = today.getMonth() + 1;
    const currentDate = today.getDate();
    return allMembers.filter(m => {
      if (!m.dob) return false;
      const d = new Date(m.dob);
      return d.getMonth() + 1 === currentMonth; // Same month
    }).sort((a,b) => {
      const da = new Date(a.dob!);
      const db = new Date(b.dob!);
      return da.getDate() - db.getDate();
    });
  };
  const birthdayMembers = getBirthdayMembers();

  const filteredMembers = allMembers.filter(m => (m.email !== 'admin@ssaa.com' && m.email !== 'editor@ssaa.com') && ((bloodFilter === '' || m.bloodGroup === bloodFilter) && (showMentorsOnly ? m.isMentor : true) && (m.name.toLowerCase().includes(searchQuery.toLowerCase()) || m.designation.toLowerCase().includes(searchQuery.toLowerCase()) || m.session.toLowerCase().includes(searchQuery.toLowerCase()) || (m.company && m.company.toLowerCase().includes(searchQuery.toLowerCase())) || m.currentAddress.toLowerCase().includes(searchQuery.toLowerCase()))));

  if (!user) return <div className="flex h-screen items-center justify-center dark:bg-dark-bg"><Loader2 className="animate-spin text-soil dark:text-soil-light" size={40} /></div>;

  const isValidPhoto = (url?: string) => { return url && url.startsWith('http') && !url.includes('ERROR'); };
  const formatChatDate = (isoString: string) => { 
     try {
       const date = new Date(isoString);
       const day = date.toLocaleString('en-GB', { day: '2-digit' });
       const month = date.toLocaleString('en-GB', { month: 'short' });
       const year = date.toLocaleString('en-GB', { year: 'numeric' });
       const time = date.toLocaleString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true }).toLowerCase();
       return `${day}-${month}-${year} ${time}`;
     } catch { return isoString; }
  };
  const membershipId = user.data?.password || user.password;
  const canPost = user.role === 'admin' || user.role === 'editor';
  const careerPosts = posts.filter(p => p.category === 'Career');
  const visibleDonations = user.role === 'admin' ? donations : donations.filter(d => d.donorEmail === user.email);

  // Helper for Sidebar Date
  const formatShortDate = (iso: string) => {
    try {
      const d = new Date(iso);
      return d.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
    } catch { return ''; }
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-dark-bg transition-colors pt-28 pb-4" ref={topRef}>

      {/* 1. ADMIN NOTICE TICKER */}
      {adminNotice && (
