export const createEvent = async (eventData: Omit<Event, 'id'>, imageFile: File | null): Promise<boolean> => {
  let imageUrl = eventData.imageUrl || "https://picsum.photos/seed/event/800/400";
  if (imageFile) {
    try { imageUrl = await uploadToImgBB(imageFile); } 
    catch (e) { console.warn("Event image upload failed"); }
  }

  const newEvent: Event = {
    ...eventData,
    id: Date.now(),
    imageUrl
  };

  // Local Save
  const events = getLocalEvents();
  events.push(newEvent);
  localStorage.setItem(EVENTS_KEY, JSON.stringify(events));

  // Server Save
  if (GOOGLE_SCRIPT_URL && GOOGLE_SCRIPT_URL.includes('script.google.com')) {
    try {
      await callScript('createEvent', { data: newEvent });
    } catch (e) { console.warn("Event created locally only"); }
  }
  return true;
};

export const updateEvent = async (eventData: Event, imageFile: File | null): Promise<boolean> => {
  let imageUrl = eventData.imageUrl;
  if (imageFile) {
    try { imageUrl = await uploadToImgBB(imageFile); } 
    catch (e) { console.warn("Event image upload failed"); }
  }

  const updatedEvent = { ...eventData, imageUrl };

  // Local Update
  const events = getLocalEvents();
  const idx = events.findIndex(e => e.id.toString() === eventData.id.toString());
  if (idx !== -1) {
    events[idx] = updatedEvent;
    localStorage.setItem(EVENTS_KEY, JSON.stringify(events));
  }

  // Server Update
  if (GOOGLE_SCRIPT_URL && GOOGLE_SCRIPT_URL.includes('script.google.com')) {
    try {
      await callScript('updateEvent', { data: updatedEvent });
    } catch (e) { console.warn("Event updated locally only"); }
  }
  return true;
};

