                                 <button 
                                   onClick={() => openModal('eventTicket', { event, rsvp: myRsvp })}
                                   className="flex-1 bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300 py-2 rounded-lg font-bold text-sm flex items-center justify-center hover:bg-green-200 dark:hover:bg-green-900/50 transition-colors"
                                 >
                                   <Ticket size={16} className="mr-2" /> View Ticket
                                 </button>
                               ) : (
                                  <span className="flex-1 bg-yellow-100 dark:bg-yellow-900/30 text-yellow-700 dark:text-yellow-300 py-2 rounded-lg font-bold text-sm text-center">
                                    Payment Pending
                                  </span>
                               )}
                             </div>
                           ) : (
                             <button 
                               onClick={() => handleRSVP(event)}
                               disabled={isSubmittingRSVP}
                               className="w-full bg-soil hover:bg-soil-dark dark:bg-soil-light dark:hover:bg-soil text-white py-2 rounded-lg font-bold text-sm transition-colors shadow-sm disabled:opacity-70"
                             >
                               {isSubmittingRSVP ? "Processing..." : "RSVP Now"}
                             </button>
                           )}
                        </div>
                      </div>
                   </div>
                 );
               })}
               {events.length === 0 && <p className="col-span-2 text-center text-gray-500 dark:text-gray-400 py-12">No upcoming events scheduled.</p>}
            </div>
          </div>
        )}

        {/* ... (Other Tabs - Unchanged) ... */}
        {/* CHAT VIEW - ADMIN MESSENGER STYLE & MEMBER CHAT */}
        {activeTab === 'chat' && user && (
          <div className="bg-white dark:bg-dark-card rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden h-[600px] flex flex-col md:flex-row">

            {/* LEFT SIDEBAR (Admin Only) */}
            {user.role === 'admin' && (
              <div className="w-full md:w-1/3 border-r border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-800 flex flex-col h-1/3 md:h-full border-b md:border-b-0">
                  <div className="p-2 border-b border-gray-200 dark:border-gray-700">
                    <div className="flex space-x-2 bg-white dark:bg-gray-700 rounded-lg p-1 border border-gray-100 dark:border-gray-600">
                      <button onClick={() => setAdminChatMode('BATCH')} className={`flex-1 py-1 text-[10px] uppercase font-bold rounded ${adminChatMode === 'BATCH' ? 'bg-soil text-white' : 'text-gray-500 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-600'}`}>Batches</button>
                      <button onClick={() => setAdminChatMode('DM')} className={`flex-1 py-1 text-[10px] uppercase font-bold rounded ${adminChatMode === 'DM' ? 'bg-soil text-white' : 'text-gray-500 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-600'}`}>Direct</button>
                    </div>
                  </div>

                  <div className="overflow-y-auto flex-1 custom-scrollbar">
                    {adminChatMode === 'BATCH' ? (
                       uniqueSessions.map(session => (
                         <button key={session} onClick={() => setAdminChatSession(session)} className={`w-full text-left px-4 py-3 hover:bg-white dark:hover:bg-gray-700 border-b border-gray-100 dark:border-gray-700 transition-all ${adminChatSession === session ? 'bg-white dark:bg-gray-700 border-l-4 border-l-soil' : ''}`}>
                           <span className="font-bold text-gray-700 dark:text-gray-200 text-sm">Session {session}</span>
                           <p className="text-[10px] text-gray-400">Group Discussion</p>
                         </button>
                       ))
                    ) : (
                      // MESSENGER LIST
                      conversations.length > 0 ? conversations.map(c => (
                        <button key={c.email} onClick={() => setAdminSelectedMemberEmail(c.email)} className={`w-full text-left px-3 py-3 hover:bg-white dark:hover:bg-gray-700 border-b border-gray-100 dark:border-gray-700 transition-all ${adminSelectedMemberEmail === c.email ? 'bg-white dark:bg-gray-700 border-l-4 border-l-soil shadow-sm' : ''}`}>
                           <div className="flex items-start">
                             <div className="relative">
                               <div className="w-10 h-10 rounded-full bg-gray-200 dark:bg-gray-600 mr-2 overflow-hidden border border-gray-200 dark:border-gray-600">
                                 {c.photoUrl ? <img src={c.photoUrl} className="w-full h-full object-cover" /> : <span className="flex items-center justify-center h-full text-xs font-bold text-gray-500 dark:text-gray-400">{c.name[0]}</span>}
                               </div>
                             </div>
                             <div className="flex-1 min-w-0">
                               <div className="flex justify-between items-baseline mb-0.5">
                                 <span className="font-bold text-sm text-gray-800 dark:text-gray-200 truncate">{c.name}</span>
                                 <span className="text-[9px] text-gray-400 whitespace-nowrap ml-1">{formatShortDate(c.timestamp)}</span>
                               </div>
                               <p className="text-[11px] text-gray-500 dark:text-gray-400 truncate">{c.lastMessage}</p>
                             </div>
                           </div>
                        </button>
                      )) : <div className="p-4 text-center text-xs text-gray-400">No conversations yet</div>
                    )}
                  </div>
              </div>
            )}

            {/* RIGHT CHAT AREA */}
            <div className={`flex-col h-full relative flex ${user.role === 'admin' ? 'w-full md:w-2/3 h-2/3 md:h-full' : 'w-full'}`}>

              {/* Header */}
              <div className="p-4 bg-soil dark:bg-soil-dark text-white flex flex-row justify-between items-center z-10 shadow-md">

                {/* Left Side Info */}
                <div className="flex-1 min-w-0">
                   {user.role === 'member' && memberChatMode === 'BATCH' ? (
                     <div className="flex flex-col items-start gap-1">
                       <h3 className="font-bold text-2xl md:text-3xl leading-none">Batch Chat</h3>
                       <div className="bg-white/20 px-3 py-1 rounded-lg border border-white/10 backdrop-blur-sm flex flex-col justify-center w-fit">
                           <p className="font-bold text-sm leading-none">{user.data?.session || 'N/A'}</p>
                       </div>
                       <p className="text-xs md:text-sm text-gray-300 mt-0.5 truncate">Discuss with your batchmates</p>
                     </div>
                   ) : (
                     // Admin Mode or Admin Support Mode
                     <div>
                        <div className="flex items-center gap-3">
                          <h3 className="font-bold text-xl md:text-2xl flex items-center gap-2">
                            {user.role === 'admin' 
                              ? (adminChatMode === 'BATCH' ? 'Batch Chat' : 'Admin Support') 
                              : 'Admin Support'}
                          </h3>
                        </div>
                        <p className="text-xs text-gray-200 mt-1 opacity-90 truncate">
                          {user.role === 'admin' 
                            ? (adminChatMode === 'BATCH' ? `Viewing: ${adminChatSession || 'Select Session'}` : `Chatting with: ${conversations.find(c=>c.email===adminSelectedMemberEmail)?.name || 'Select User'}`)
                            : 'Direct line to Association Admins'}
                        </p>
                     </div>
                   )}
                </div>

                {/* Right Side Controls */}
                <div className="flex flex-col items-end gap-2 pl-2">
                  {/* Live Refresh Icon */}
                  <button 
                    onClick={() => fetchMessages()} 
                    className="w-8 h-8 md:w-10 md:h-10 flex items-center justify-center bg-white/10 hover:bg-white/20 rounded-lg transition-colors backdrop-blur-sm border border-white/10 relative"
                    title="Refresh Chat"
                  >
                    <RefreshCw size={18} className={`text-white ${isRefreshingChat ? 'animate-spin' : ''}`} />
                    {/* Live Indicator Dot */}
                    <span className="absolute top-1.5 right-1.5 flex h-2 w-2">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-2 w-2 bg-green-500"></span>
                    </span>
                  </button>

                  {user.role === 'member' && (
                    <button 
                      onClick={() => setMemberChatMode(prev => prev === 'BATCH' ? 'ADMIN' : 'BATCH')}
                      className={`px-3 py-1.5 md:px-4 md:py-2 rounded-lg shadow-lg transition-all font-bold text-xs md:text-sm leading-tight whitespace-nowrap
                        ${memberChatMode === 'BATCH' 
                          ? 'bg-white text-soil hover:bg-gray-100' 
                          : 'bg-leaf text-white hover:bg-leaf-dark'}`}
                    >
                      {memberChatMode === 'BATCH' ? 'Admin Support' : 'Batch Chat'}
                    </button>
                  )}
                </div>
              </div>

              {/* Messages */}
              <div className="flex-grow p-4 overflow-y-auto bg-gray-50 dark:bg-gray-900 space-y-3">
                {chatMessages.length === 0 ? (
                  <div className="text-center text-gray-400 mt-10">
                    <MessageSquare size={40} className="mx-auto mb-2 opacity-20" />
                    <p className="text-sm">No messages yet.</p>
                  </div>
                ) : (
                  chatMessages.map((msg, idx) => (
                    <div key={idx} className={`flex ${msg.isMe ? 'justify-end' : 'justify-start'}`}>
                      <div className={`flex max-w-[85%] ${msg.isMe ? 'flex-row-reverse' : 'flex-row'}`}>
                        <div className="flex-shrink-0 w-8 h-8 rounded-full overflow-hidden bg-gray-200 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 mt-1">
                          {isValidPhoto(msg.senderPhoto) ? (<img src={msg.senderPhoto} alt="" className="w-full h-full object-cover" />) : (<div className="w-full h-full flex items-center justify-center bg-soil text-white text-xs font-bold">{msg.senderName.charAt(0)}</div>)}
                        </div>
                        <div className={`mx-2 p-3 rounded-2xl shadow-sm text-sm ${msg.isMe ? 'bg-soil text-white rounded-tr-none' : 'bg-white dark:bg-gray-800 text-gray-800 dark:text-gray-200 rounded-tl-none border border-gray-100 dark:border-gray-700'}`}>
                          {!msg.isMe && <p className="text-[10px] font-bold text-leaf dark:text-leaf-accent mb-1">{msg.senderName}</p>}
                          <p>{msg.message}</p>
                          <p className={`text-[9px] mt-1 text-right ${msg.isMe ? 'text-[#e3e3e3]' : 'text-gray-400'}`}>{formatChatDate(msg.timestamp)}</p>
                        </div>
                      </div>
                    </div>
                  ))
                )}
                <div ref={chatEndRef} />
              </div>

              {/* Input */}
              <form onSubmit={handleSendMessage} className="p-3 bg-white dark:bg-dark-card border-t border-gray-100 dark:border-gray-700 flex gap-3 items-center">
                <input type="text" value={newMessage} onChange={(e) => setNewMessage(e.target.value)} placeholder="Type a message..." className="flex-grow px-4 py-2 text-sm border border-gray-300 dark:border-gray-600 rounded-full focus:ring-2 focus:ring-soil focus:border-transparent outline-none bg-white dark:bg-gray-800 text-gray-900 dark:text-white" />
                <button type="submit" disabled={!newMessage.trim()} className="bg-leaf hover:bg-leaf-dark text-white p-2 rounded-full disabled:opacity-50 transition-colors flex-shrink-0 shadow-md transform hover:scale-105 active:scale-95"><Send size={18} /></button>
              </form>
            </div>
          </div>
        )}

        {/* ... (Admin Table, Search, Donation, Career, Profile, Edit Modal - Unchanged) ... */}

        {/* PROFILE VIEW WITH WIDGETS */}
        {activeTab === 'profile' && user.data && (
           <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
             {/* LEFT COLUMN: Personal Info & Widgets */}
             <div className="col-span-1 space-y-6">
               {/* Personal Info Card */}
               <div className="bg-white dark:bg-dark-card rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 p-6">
                 <div className="flex justify-between items-start mb-4"><h3 className="font-bold text-lg text-gray-900 dark:text-white">Personal Info</h3><button onClick={handleOpenEditProfile} className="text-leaf hover:text-leaf-dark p-2 bg-leaf/10 dark:bg-leaf/20 rounded-full transition-colors"><Edit size={16} /></button></div>
                 <div className="space-y-4">
                   <div className="flex items-center text-gray-600 dark:text-gray-300"><Mail size={18} className="mr-3" /> {user.email}</div>
                   <div className="flex items-center text-gray-600 dark:text-gray-300"><Phone size={18} className="mr-3" /> {user.data.phone}</div>
                   <div className="flex items-center text-gray-600 dark:text-gray-300"><MapPin size={18} className="mr-3" /> {user.data.currentAddress}</div>
                   <div className="flex items-center text-gray-600 dark:text-gray-300"><Heart size={18} className="mr-3 text-red-500" /> Blood Group: {user.data.bloodGroup || 'N/A'}</div>
                   {user.data.dob && <div className="flex items-center text-gray-600 dark:text-gray-300"><Gift size={18} className="mr-3 text-pink-500" /> DOB: {user.data.dob}</div>}
                 </div>
               </div>

               {/* 2. BIRTHDAY CORNER WIDGET */}
               <div className="bg-white dark:bg-dark-card rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 p-6">
                  <h3 className="font-bold text-lg text-gray-900 dark:text-white mb-4 flex items-center text-pink-600"><Gift size={20} className="mr-2"/> Birthday Corner</h3>
                  {birthdayMembers.length > 0 ? (
                    <div className="space-y-4">
                      {birthdayMembers.map((m, idx) => {
                         const isToday = new Date().getDate() === new Date(m.dob!).getDate();
                         return (
                           <div key={idx} className={`flex items-center gap-3 p-3 rounded-lg ${isToday ? 'bg-pink-50 dark:bg-pink-900/20 border border-pink-100 dark:border-pink-800' : 'bg-gray-50 dark:bg-gray-800'}`}>
                             <div className="w-10 h-10 rounded-full overflow-hidden bg-gray-200 dark:bg-gray-700">
                               {isValidPhoto(m.photoUrl) ? <img src={m.photoUrl} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center font-bold text-gray-500 dark:text-gray-400 text-xs">{m.name[0]}</div>}
                             </div>
                             <div className="flex-1 min-w-0">
                               <p className="font-bold text-sm truncate text-gray-800 dark:text-gray-200">{m.name}</p>
                               <p className="text-xs text-gray-500 dark:text-gray-400">Batch {m.batch} • {new Date(m.dob!).getDate()} {new Date(m.dob!).toLocaleString('default', { month: 'short' })}</p>
                             </div>
                             {isToday && <span className="text-[10px] bg-pink-500 text-white px-2 py-0.5 rounded-full font-bold">Today!</span>}
                           </div>
                         );
                      })}
                    </div>
                  ) : (
                    <p className="text-sm text-gray-500 dark:text-gray-400 text-center py-4">No birthdays in this month.</p>
                  )}
               </div>

               {/* 3. DIGITAL ID CARD WIDGET */}
               <div className="bg-gradient-to-br from-soil to-soil-light dark:from-soil-dark dark:to-soil rounded-xl shadow-md p-6 text-white text-center">
                  <CreditCard size={40} className="mx-auto mb-3 opacity-90" />
                  <h3 className="font-bold text-lg mb-1">Digital Alumni ID</h3>
                  <p className="text-xs text-soil-light/200 mb-4 px-2">Generate your official membership card to use for events and benefits.</p>
                  <button onClick={() => openModal('idCard', user)} className="bg-white text-soil font-bold py-2 px-6 rounded-full text-sm shadow hover:bg-gray-100 transition-colors">Generate Card</button>
               </div>
             </div>

             {/* RIGHT COLUMN: Professional Info */}
             <div className="col-span-1 lg:col-span-2 space-y-8">
               <div className="bg-white dark:bg-dark-card rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 p-6">
                 <h3 className="font-bold text-lg text-gray-900 dark:text-white mb-4">Professional Information</h3>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div className="bg-gray-50 dark:bg-gray-800 p-4 rounded-lg"><p className="text-sm text-gray-500 dark:text-gray-400 mb-1">Designation</p><p className="font-medium text-gray-900 dark:text-white">{user.data.designation}</p></div>
                   <div className="bg-gray-50 dark:bg-gray-800 p-4 rounded-lg"><p className="text-sm text-gray-500 dark:text-gray-400 mb-1">Company / Organization</p><p className="font-medium text-gray-900 dark:text-white">{user.data.company || 'Not listed'}</p></div>
                 </div>
               </div>

               {/* Mentorship Status Block */}
               {user.data.isMentor ? (
                  <div className="bg-indigo-50 dark:bg-indigo-900/20 rounded-xl p-6 border border-indigo-100 dark:border-indigo-800 flex items-center justify-between">
                     <div>
                       <h3 className="font-bold text-lg text-indigo-900 dark:text-indigo-300 mb-1 flex items-center"><Star className="mr-2 fill-current" size={20}/> You are a Mentor</h3>
                       <p className="text-sm text-indigo-700 dark:text-indigo-400">Thank you for contributing to the community. Students can find you in the directory.</p>
                     </div>
                     <button onClick={handleOpenEditProfile} className="text-xs font-bold bg-white dark:bg-indigo-800 text-indigo-700 dark:text-indigo-200 px-3 py-2 rounded-lg border border-indigo-200 dark:border-indigo-700 hover:bg-indigo-100 dark:hover:bg-indigo-700">Settings</button>
                  </div>
               ) : (
                  <div className="bg-gray-50 dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700 border-dashed flex flex-col md:flex-row items-center justify-between gap-4">
                     <div>
                       <h3 className="font-bold text-lg text-gray-700 dark:text-gray-300 mb-1">Become a Mentor</h3>
                       <p className="text-sm text-gray-500 dark:text-gray-400">Share your professional experience with juniors.</p>
                     </div>
                     <button onClick={handleOpenEditProfile} className="text-sm font-bold bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-300 px-4 py-2 rounded-lg border border-gray-300 dark:border-gray-600 hover:bg-gray-100 dark:hover:bg-gray-600 whitespace-nowrap">Enable Mentorship</button>
                  </div>
               )}

               {/* Placeholder for more content */}
               <div className="bg-blue-50 dark:bg-blue-900/20 rounded-xl p-6 border border-blue-100 dark:border-blue-800">
                  <h3 className="font-bold text-lg text-blue-900 dark:text-blue-300 mb-2">Member Benefits</h3>
                  <ul className="list-disc list-inside text-sm text-blue-800 dark:text-blue-400 space-y-2">
                    <li>Access to exclusive networking events</li>
                    <li>Mentorship opportunities with seniors</li>
                    <li>Voting rights in association elections</li>
                    <li>Priority registration for annual reunions</li>
                  </ul>
               </div>
             </div>
           </div>
        )}

        {/* ... (Rest of Tabs - Unchanged) ... */}
        {/* ... (Admin Table, Search, Donation, Career, Profile, Edit Modal - Unchanged) ... */}

        {/* PROFILE VIEW WITH WIDGETS */}
        {/* ... (Kept Unchanged) ... */}

      </div>

      {/* Edit Profile Modal (Dark Mode Support) */}
      {isEditingProfile && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4">
          <div className="bg-white dark:bg-dark-card rounded-xl shadow-xl w-full max-w-lg overflow-hidden max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-gray-800 sticky top-0 z-10">
              <h3 className="text-lg font-bold text-gray-900 dark:text-white">Edit Profile</h3>
              <button onClick={() => setIsEditingProfile(false)} className="text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-white"><XIcon size={20} /></button>
            </div>
            <form onSubmit={handleProfileUpdate} className="p-6 space-y-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Profile Picture</label>
                <div className="flex items-center gap-4">
                  <div className="w-16 h-16 rounded-full border border-gray-200 dark:border-gray-600 overflow-hidden bg-gray-100 dark:bg-gray-700">{editPhotoPreview ? (<img src={editPhotoPreview} alt="Preview" className="w-full h-full object-cover" />) : (<div className="w-full h-full flex items-center justify-center bg-soil text-white text-xl font-bold">P</div>)}</div>
                  <label className="cursor-pointer bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-300 px-4 py-2 rounded-lg text-sm font-medium hover:bg-gray-50 dark:hover:bg-gray-600 transition-colors">Change Photo<input type="file" className="hidden" accept="image/*" onChange={handleProfilePhotoChange} /></label>
                </div>
              </div>

              {/* MENTOR TOGGLE */}
              <div className="bg-indigo-50 dark:bg-indigo-900/30 p-4 rounded-lg border border-indigo-100 dark:border-indigo-800 flex items-start gap-3">
                 <input 
                   type="checkbox" 
                   id="isMentor"
                   checked={editProfileForm.isMentor}
                   onChange={e => setEditProfileForm({...editProfileForm, isMentor: e.target.checked})}
                   className="mt-1 w-4 h-4 text-indigo-600 rounded focus:ring-indigo-500"
                 />
                 <div>
                    <label htmlFor="isMentor" className="block text-sm font-bold text-indigo-900 dark:text-indigo-200 cursor-pointer">Available for Mentorship</label>
                    <p className="text-xs text-indigo-700 dark:text-indigo-400 mt-1">Check this if you are willing to guide junior alumni or students with career advice.</p>
                 </div>
              </div>

              <div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Current Designation</label><input required type="text" value={editProfileForm.designation} onChange={e => setEditProfileForm({...editProfileForm, designation: e.target.value})} className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white" /></div>
              <div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Company/Organization</label><input type="text" value={editProfileForm.company} onChange={e => setEditProfileForm({...editProfileForm, company: e.target.value})} className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white" /></div>
              <div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Blood Group</label><select value={editProfileForm.bloodGroup} onChange={e => setEditProfileForm({...editProfileForm, bloodGroup: e.target.value})} className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white"><option value="">Select...</option>{['A+','A-','B+','B-','AB+','AB-','O+','O-'].map(b=><option key={b} value={b}>{b}</option>)}</select></div>
              <div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Date of Birth</label><input type="date" value={editProfileForm.dob} onChange={e => setEditProfileForm({...editProfileForm, dob: e.target.value})} className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white" /></div>
              <div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Current Address</label><textarea required rows={2} value={editProfileForm.currentAddress} onChange={e => setEditProfileForm({...editProfileForm, currentAddress: e.target.value})} className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-soil outline-none bg-white dark:bg-gray-700 text-gray-900 dark:text-white" /></div>
              <div className="flex justify-end pt-2"><button type="button" onClick={() => setIsEditingProfile(false)} className="mr-3 px-4 py-2 text-gray-700 dark:text-gray-300 font-medium hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors">Cancel</button><button type="submit" disabled={isUpdatingProfile} className="px-6 py-2 bg-leaf text-white font-medium rounded-lg hover:bg-leaf-dark flex items-center shadow-sm disabled:opacity-70">{isUpdatingProfile ? <RefreshCw className="animate-spin mr-2 w-4 h-4" /> : null} Save Changes</button></div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

